const EMBEDDED_PROPS_SPRITES_URI = 'data:image/png;base64,';

// ============================================================================
// RUNTIME CHROMA-KEY & NORMALISIERUNGS-ENGINE FÜR GENERIERTE SPRITE-BÖGEN
// Erkennt automatisch, ob ein Bogen einen Magenta-Hintergrund (#FF00FF) besitzt,
// stellt jedes Objekt haarscharf frei (inkl. Despill) und normiert das Raster!
// ============================================================================
window.processAndNormalizeSpriteSheet = function(rawImg, cols, rows, targetCellW, targetCellH, mode = 'world') {
  try {
    const tmp = document.createElement('canvas');
    tmp.width = rawImg.naturalWidth || rawImg.width;
    tmp.height = rawImg.naturalHeight || rawImg.height;
    const tctx = tmp.getContext('2d', { willReadFrequently: true });
    tctx.drawImage(rawImg, 0, 0);
    const imgData = tctx.getImageData(0, 0, tmp.width, tmp.height);
    const d = imgData.data;

    // Prüfen, ob die Bildecken Magenta (#FF00FF) sind (oder ob das PNG bereits transparent ist)
    let magCorners = 0;
    const samplePts = [
      0, (tmp.width - 1) * 4,
      ((tmp.height - 1) * tmp.width) * 4,
      ((tmp.height - 1) * tmp.width + (tmp.width - 1)) * 4,
      (Math.floor(tmp.height * 0.5) * tmp.width + 2) * 4
    ];
    for (const idx of samplePts) {
      if (d[idx + 3] > 200 && Math.min(d[idx], d[idx + 2]) - d[idx + 1] > 85) magCorners++;
    }
    const needsChromaKey = magCorners >= 2;

    if (!needsChromaKey && tmp.width === cols * targetCellW && tmp.height === rows * targetCellH) {
      return rawImg;
    }

    const srcCellW = tmp.width / cols;
    const srcCellH = tmp.height / rows;

    if (needsChromaKey) {
      for (let py = 0; py < tmp.height; py++) {
        const rowIdx = Math.floor(py / srcCellH);
        for (let px = 0; px < tmp.width; px++) {
          const colIdx = Math.floor(px / srcCellW);
          const i = (py * tmp.width + px) * 4;
          const r = d[i], g = d[i + 1], b = d[i + 2];
          const pExc = Math.min(r, b) - g;
          const isGhostShipCell = (mode === 'ships' && (rowIdx * cols + colIdx) >= 7);

          let alpha = isGhostShipCell
            ? Math.max(0, Math.min(1, (140 - pExc) / 68))
            : Math.max(0, Math.min(1, (86 - pExc) / 48));
          if (alpha < 0.10) alpha = 0;

          if (pExc > -4 && alpha > 0) {
            if (isGhostShipCell) {
              d[i]     = Math.min(255, Math.round(g * 0.24));
              d[i + 1] = Math.min(255, Math.round(Math.max(g, Math.min(r, b) * 0.68)));
              d[i + 2] = Math.min(255, Math.round(g * 0.54));
            } else {
              d[i]     = Math.min(255, Math.round(Math.min(r, g * 1.12 + 12)));
              d[i + 2] = Math.min(255, Math.round(Math.min(b, g * 0.80 + 8)));
            }
          }
          d[i + 3] = Math.round(alpha * 255);
        }
      }
      tctx.putImageData(imgData, 0, 0);
    }

    const out = document.createElement('canvas');
    out.width = cols * targetCellW;
    out.height = rows * targetCellH;
    const octx = out.getContext('2d');

    const sprScaleL = [0.46, 0.56, 0.62, 0.66, 0.74, 0.82, 0.90, 0.64, 0.86, 0.90];
    const sprScaleW = [0.30, 0.34, 0.44, 0.35, 0.40, 0.48, 0.52, 0.36, 0.50, 0.52];

    for (let rIdx = 0; rIdx < rows; rIdx++) {
      for (let cIdx = 0; cIdx < cols; cIdx++) {
        const cellIdx = rIdx * cols + cIdx;
        const sx0 = Math.floor(cIdx * srcCellW) + 3;
        const sy0 = Math.floor(rIdx * srcCellH) + 3;
        const sw = Math.floor(srcCellW) - 6;
        const sh = Math.floor(srcCellH) - 6;
        const sub = tctx.getImageData(sx0, sy0, sw, sh);
        const sd = sub.data;

        let minX = sw, maxX = -1, minY = sh, maxY = -1;
        for (let y = 0; y < sh; y++) {
          for (let x = 0; x < sw; x++) {
            if (sd[(y * sw + x) * 4 + 3] > 28) {
              if (x < minX) minX = x;
              if (x > maxX) maxX = x;
              if (y < minY) minY = y;
              if (y > maxY) maxY = y;
            }
          }
        }
        if (maxX < minX || maxY < minY) continue;

        const bw = maxX - minX + 1;
        const bh = maxY - minY + 1;
        const dxCell = cIdx * targetCellW;
        const dyCell = rIdx * targetCellH;

        if (mode === 'ships') {
          const tw = Math.round(targetCellW * 0.88 * (sprScaleL[cellIdx] || 0.65));
          const th = Math.round(targetCellH * 0.88 * (sprScaleW[cellIdx] || 0.38) * 1.24);
          const ox = dxCell + Math.round((targetCellW - tw) / 2);
          const oy = dyCell + Math.round((targetCellH - th) / 2);
          octx.drawImage(tmp, sx0 + minX, sy0 + minY, bw, bh, ox, oy, tw, th);
        } else if (mode === 'icons') {
          const pad = Math.round(targetCellW * 0.08);
          const maxDim = targetCellW - pad * 2;
          const sc = Math.min(maxDim / bw, maxDim / bh);
          const tw = Math.max(1, Math.round(bw * sc));
          const th = Math.max(1, Math.round(bh * sc));
          const ox = dxCell + Math.round((targetCellW - tw) / 2);
          const oy = dyCell + Math.round((targetCellH - th) / 2);
          octx.drawImage(tmp, sx0 + minX, sy0 + minY, bw, bh, ox, oy, tw, th);
        } else {
          // 'world' & 'props': weichen Bodenschatten ergänzen & am Fußpunkt (anchor ~0.78) ausrichten!
          const maxBox = Math.round(targetCellW * 0.86);
          const sc = Math.min(maxBox / bw, maxBox / bh);
          const tw = Math.max(1, Math.round(bw * sc));
          const th = Math.max(1, Math.round(bh * sc));
          const ox = dxCell + Math.round((targetCellW - tw) / 2);
          const bottomTarget = Math.round(targetCellH * 0.86);
          const oy = dyCell + Math.max(4, bottomTarget - th);

          octx.save();
          const shGrad = octx.createRadialGradient(
            dxCell + targetCellW * 0.5, dyCell + bottomTarget - 6, 4,
            dxCell + targetCellW * 0.5, dyCell + bottomTarget - 6, tw * 0.48
          );
          shGrad.addColorStop(0, 'rgba(4, 10, 18, 0.42)');
          shGrad.addColorStop(1, 'rgba(4, 10, 18, 0)');
          octx.fillStyle = shGrad;
          octx.beginPath();
          octx.ellipse(dxCell + targetCellW * 0.5, dyCell + bottomTarget - 6, tw * 0.48, Math.max(10, tw * 0.21), 0, 0, Math.PI * 2);
          octx.fill();
          octx.restore();

          octx.drawImage(tmp, sx0 + minX, sy0 + minY, bw, bh, ox, oy, tw, th);
        }
      }
    }
    return out;
  } catch (err) {
    return rawImg;
  }
};

function loadSmartSheet(sheetObj, fileCandidates, fallbackDataUri, rows, mode) {
  let tryIdx = 0;
  const raw = new Image();
  raw.onload = () => {
    sheetObj.img = window.processAndNormalizeSpriteSheet(raw, sheetObj.cols, rows, sheetObj.cellW, sheetObj.cellH, mode);
    sheetObj.loaded = true;
    // Insel-Props-Cache zurücksetzen, falls das Sheet nachträglich geladen wurde
    if (mode === 'props' && typeof LANDMASSES !== 'undefined') {
      LANDMASSES.forEach(l => { delete l.props25d; });
    }
  };
  raw.onerror = () => {
    tryIdx++;
    if (tryIdx < fileCandidates.length) {
      raw.src = fileCandidates[tryIdx];
    } else if (fallbackDataUri && !sheetObj.usedFallback) {
      sheetObj.usedFallback = true;
      raw.src = fallbackDataUri;
    }
  };
  raw.src = fileCandidates[0];
}

