const EMBEDDED_UI_ICONS_URI = 'data:image/png;base64,';

(function initGeneratedUiIcons() {
  const files = ['ui_icons.png', 'ui_icons.jpg', 'ui_icons.jfif'];
  let idx = 0;
  let usedFallback = false;
  const raw = new Image();
  raw.onload = () => {
    const cnv = window.processAndNormalizeSpriteSheet(raw, 8, 8, 64, 64, 'icons');
    let dUrl = EMBEDDED_UI_ICONS_URI;
    let cnvEl = raw;
    if (cnv && cnv.toDataURL) {
      cnvEl = cnv;
      dUrl = cnv.toDataURL('image/png');
    } else {
      const tc = document.createElement('canvas');
      tc.width = raw.naturalWidth || raw.width;
      tc.height = raw.naturalHeight || raw.height;
      tc.getContext('2d').drawImage(raw, 0, 0);
      cnvEl = tc;
      dUrl = tc.toDataURL('image/png');
    }
    window.UI_ICON_SHEET.cellW = cnvEl.width / 8;
    window.UI_ICON_SHEET.cellH = cnvEl.height / 8;
    window.UI_ICON_SHEET.canvas = cnvEl;
    window.UI_ICON_SHEET.dataUrl = dUrl;
    window.UI_ICON_SHEET.loaded = true;
    const st = document.createElement('style');
    st.textContent = `.game-ui-icon { background-image: url("${dUrl}"); }`;
    document.head.appendChild(st);
    window.upgradeDomEmojisToGeneratedIcons(document.body);
  };
  raw.onerror = () => {
    idx++;
    if (idx < files.length) raw.src = files[idx];
    else if (!usedFallback) { usedFallback = true; raw.src = EMBEDDED_UI_ICONS_URI; }
  };
  raw.src = files[0];
})();

const EMOJI_TOKEN_KEYS = Object.keys(window.UI_ICON_SHEET.emojiMap).sort((a, b) => b.length - a.length);
const EMOJI_SPLIT_REGEX = new RegExp('(' + EMOJI_TOKEN_KEYS.map(k => k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|') + ')', 'g');

window.upgradeDomEmojisToGeneratedIcons = function(rootNode) {
  if (!window.UI_ICON_SHEET || !window.UI_ICON_SHEET.loaded || !rootNode) return;
  const walker = document.createTreeWalker(rootNode, NodeFilter.SHOW_TEXT, null);
  const toReplace = [];
  let node;
  while ((node = walker.nextNode())) {
    const p = node.parentNode;
    if (!p) continue;
    const tag = p.nodeName;
    if (tag === 'SCRIPT' || tag === 'STYLE' || tag === 'TEXTAREA' || tag === 'TITLE') continue;
    if (tag === 'OPTION') {
      if (EMOJI_SPLIT_REGEX.test(node.nodeValue)) {
        EMOJI_SPLIT_REGEX.lastIndex = 0;
        node.nodeValue = node.nodeValue.replace(EMOJI_SPLIT_REGEX, '').replace(/\s{2,}/g, ' ').trim();
      }
      continue;
    }
    if (EMOJI_SPLIT_REGEX.test(node.nodeValue)) {
      EMOJI_SPLIT_REGEX.lastIndex = 0;
      toReplace.push(node);
    }
  }
  for (const tNode of toReplace) {
    const parts = tNode.nodeValue.split(EMOJI_SPLIT_REGEX);
    if (parts.length <= 1) continue;
    const frag = document.createDocumentFragment();
    for (const part of parts) {
      if (!part) continue;
      const iconIdx = window.UI_ICON_SHEET.emojiMap[part];
      if (iconIdx !== undefined) {
        const sp = document.createElement('span');
        sp.className = 'game-ui-icon';
        const col = iconIdx % 8, row = Math.floor(iconIdx / 8);
        sp.style.backgroundPosition = `${(col / 7) * 100}% ${(row / 7) * 100}%`;
        frag.appendChild(sp);
      } else {
        frag.appendChild(document.createTextNode(part));
      }
    }
    if (tNode.parentNode) tNode.parentNode.replaceChild(frag, tNode);
  }
};

// MutationObserver hält sämtliche dynamisch gerenderten Menüs & HUD-Elemente automatisch Emoji-frei!
window.addEventListener('DOMContentLoaded', () => {
  const obs = new MutationObserver(mutations => {
    if (!window.UI_ICON_SHEET || !window.UI_ICON_SHEET.loaded) return;
    for (const m of mutations) {
      if (m.type === 'childList') {
        m.addedNodes.forEach(n => {
          if (n.nodeType === 1 && !n.classList.contains('game-ui-icon')) {
            window.upgradeDomEmojisToGeneratedIcons(n);
          } else if (n.nodeType === 3 && n.parentNode) {
            window.upgradeDomEmojisToGeneratedIcons(n.parentNode);
          }
        });
      } else if (m.type === 'characterData' && m.target && m.target.parentNode) {
        window.upgradeDomEmojisToGeneratedIcons(m.target.parentNode);
      }
    }
  });
  obs.observe(document.body, { childList: true, subtree: true, characterData: true });
});

// Zeichnet beliebige Canvas-Texte mit mehreren eingebetteten 1714-Icons (ohne System-Emojis!)
window.drawCanvasIconLabel = function(ctx, rawText, x, y, iconPx = 15, maxWidth = null) {
  const str = String(rawText || '');
  if (!window.UI_ICON_SHEET || !window.UI_ICON_SHEET.loaded || !str) {
    if (maxWidth) ctx.fillText(str, x, y, maxWidth);
    else ctx.fillText(str, x, y);
    return;
  }
  const parts = str.split(EMOJI_SPLIT_REGEX);
  if (parts.length <= 1) {
    if (maxWidth) ctx.fillText(str, x, y, maxWidth);
    else ctx.fillText(str, x, y);
    return;
  }
  const tokens = [];
  let totalW = 0;
  for (const part of parts) {
    if (!part) continue;
    const iconIdx = window.UI_ICON_SHEET.emojiMap[part];
    if (iconIdx !== undefined) {
      tokens.push({ isIcon: true, iconIdx, w: iconPx + 3 });
      totalW += iconPx + 3;
    } else {
      const tw = ctx.measureText(part).width;
      tokens.push({ isIcon: false, text: part, w: tw });
      totalW += tw;
    }
  }
  const cw = window.UI_ICON_SHEET.cellW || 64, ch = window.UI_ICON_SHEET.cellH || 64;
  const prevAlign = ctx.textAlign;
  let curX = prevAlign === 'center' ? (x - totalW / 2) : (prevAlign === 'right' ? (x - totalW) : x);
  ctx.textAlign = 'left';
  for (const tk of tokens) {
    if (tk.isIcon) {
      const sx = (tk.iconIdx % 8) * cw, sy = Math.floor(tk.iconIdx / 8) * ch;
      ctx.drawImage(window.UI_ICON_SHEET.canvas, sx, sy, cw, ch, curX + 1, y - iconPx * 0.80, iconPx, iconPx);
      curX += tk.w;
    } else {
      ctx.fillText(tk.text, curX, y);
      curX += tk.w;
    }
  }
  ctx.textAlign = prevAlign;
};

// Zeichnet ein aufrechtes 2.5D-Welt- oder Prop-Sprite un-gestaucht (optional gespiegelt!) in die isometrische Welt!
window.drawWorldSpriteUpright = function(ctx, key, wx, wy, drawW, drawH, anchorY = 0.82, flipX = false) {
  let sheet = null;
  if (window.WORLD_SPRITE_SHEET && window.WORLD_SPRITE_SHEET.loaded && window.WORLD_SPRITE_SHEET.indexMap[key] !== undefined) {
    sheet = window.WORLD_SPRITE_SHEET;
  } else if (window.PROPS_SPRITE_SHEET && window.PROPS_SPRITE_SHEET.loaded && window.PROPS_SPRITE_SHEET.indexMap[key] !== undefined) {
    sheet = window.PROPS_SPRITE_SHEET;
  }
  if (!sheet) return false;
  const idx = sheet.indexMap[key];
  const sx = (idx % sheet.cols) * sheet.cellW;
  const sy = Math.floor(idx / sheet.cols) * sheet.cellH;
  const tiltInv = 1 / (window.ISO_TILT_Y || 0.62);
  ctx.save();
  ctx.translate(wx, wy);
  ctx.scale(flipX ? -1 : 1, tiltInv);
  ctx.drawImage(sheet.img, sx, sy, sheet.cellW, sheet.cellH, -drawW / 2, -drawH * anchorY, drawW, drawH);
  ctx.restore();
  return true;
};

window.getActiveWorldBounds = function() {
  if (window.game && game.isMultiplayer && game.mpMode === 'deathmatch') {
    return { w: DM_WORLD_W, h: DM_WORLD_H, lands: DM_ARENA_ISLANDS, reefs: DM_ARENA_REEFS };
  }
  return { w: WORLD_W, h: WORLD_H, lands: LANDMASSES, reefs: CORAL_REEFS };
};

// Berechnet den Schubvektor der historischen Meeresströmungen an Position (x, y)
window.getOceanCurrentVectorAt = function(x, y) {
  if (window.game && game.isMultiplayer && game.mpMode === 'deathmatch') return { vx: 0, vy: 0, active: false };
  if (typeof OCEAN_CURRENTS === 'undefined') return { vx: 0, vy: 0, active: false };

  let vx = 0, vy = 0, found = false;
  for (const cur of OCEAN_CURRENTS) {
    const dx = cur.x2 - cur.x1, dy = cur.y2 - cur.y1;
    const lenSq = dx * dx + dy * dy;
    if (lenSq <= 0) continue;
    let tProj = ((x - cur.x1) * dx + (y - cur.y1) * dy) / lenSq;
    if (tProj < -0.05 || tProj > 1.05) continue;
    tProj = Math.max(0, Math.min(1, tProj));
    const cx = cur.x1 + tProj * dx, cy = cur.y1 + tProj * dy;
    const dist = Math.hypot(x - cx, y - cy);
    if (dist < cur.width * 0.5) {
      const falloff = 1 - (dist / (cur.width * 0.5));
      const len = Math.sqrt(lenSq);
      vx += (dx / len) * cur.speed * (0.45 + 0.55 * falloff);
      vy += (dy / len) * cur.speed * (0.45 + 0.55 * falloff);
      found = true;
    }
  }
  return { vx, vy, active: found };
};

window.buildOrganicLandmass = function(land, idx, worldW = WORLD_W, worldH = WORLD_H) {
  if (land.renderPts) return;
  let seed = (idx + 1) * 9173;
  function seededRand() {
    seed = (seed * 16807) % 2147483647;
    return (seed - 1) / 2147483646;
  }

  let pts = land.pts.map(p => [p[0], p[1]]);
  for (let pass = 0; pass < 2; pass++) {
    const next = [];
    const jitterAmp = pass === 0 ? 95 : 36;
    for (let i = 0; i < pts.length; i++) {
      const p0 = pts[i], p1 = pts[(i + 1) % pts.length];
      const dx = p1[0] - p0[0], dy = p1[1] - p0[1];
      const segLen = Math.hypot(dx, dy);
      const onBorder = (p0[0] <= 20 || p0[0] >= worldW - 20 || p0[1] <= 20 || p0[1] >= worldH - 20) &&
                       (p1[0] <= 20 || p1[0] >= worldW - 20 || p1[1] <= 20 || p1[1] >= worldH - 20);
      const nx = segLen > 0 ? -dy / segLen : 0, ny = segLen > 0 ? dx / segLen : 0;
      const j1 = onBorder ? 0 : (seededRand() - 0.5) * Math.min(jitterAmp, segLen * 0.18);
      const j2 = onBorder ? 0 : (seededRand() - 0.5) * Math.min(jitterAmp, segLen * 0.18);
      next.push([p0[0] * 0.75 + p1[0] * 0.25 + nx * j1, p0[1] * 0.75 + p1[1] * 0.25 + ny * j1]);
      next.push([p0[0] * 0.25 + p1[0] * 0.75 + nx * j2, p0[1] * 0.25 + p1[1] * 0.75 + ny * j2]);
    }
    pts = next;
  }

  land.renderPts = pts;
  land.pts = pts;

  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  pts.forEach(p => {
    if (p[0] < minX) minX = p[0]; if (p[0] > maxX) maxX = p[0];
    if (p[1] < minY) minY = p[1]; if (p[1] > maxY) maxY = p[1];
  });
  land.bbox = { minX: minX - 240, maxX: maxX + 240, minY: minY - 240, maxY: maxY + 240 };
  land.cx = (minX + maxX) / 2;
  land.cy = (minY + maxY) / 2;

  land.collisionPts = pts.map(p => {
    const dx = p[0] - land.cx, dy = p[1] - land.cy;
    const len = Math.max(1, Math.hypot(dx, dy));
    const onBorder = (p[0] <= 20 || p[0] >= worldW - 20 || p[1] <= 20 || p[1] >= worldH - 20);
    const pad = onBorder ? 0 : 44;
    return [p[0] + (dx / len) * pad, p[1] + (dy / len) * pad];
  });

  land.shoalPts = pts.map(p => {
    const dx = p[0] - land.cx, dy = p[1] - land.cy;
    const len = Math.max(1, Math.hypot(dx, dy));
    const onBorder = (p[0] <= 20 || p[0] >= worldW - 20 || p[1] <= 20 || p[1] >= worldH - 20);
    const pad = onBorder ? 0 : 98;
    return [p[0] + (dx / len) * pad, p[1] + (dy / len) * pad];
  });

  land.innerPts = pts.map(p => [land.cx + (p[0] - land.cx) * 0.76, land.cy + (p[1] - land.cy) * 0.76]);
  land.highlandPts = pts.map(p => [land.cx + (p[0] - land.cx) * 0.45, land.cy + (p[1] - land.cy) * 0.45]);

  land.trees = []; land.hills = []; land.rocks = []; land.huts = [];
  if (!land.isGhostIsle) {
    const areaApprox = (maxX - minX) * (maxY - minY);
    const numSamples = Math.min(340, Math.max(32, Math.floor(areaApprox / 55000)));
    for (let i = 0; i < numSamples; i++) {
      const tx = minX + 45 + seededRand() * Math.max(20, maxX - minX - 90);
      const ty = minY + 45 + seededRand() * Math.max(20, maxY - minY - 90);
      if (pointInPolygon(tx, ty, land.innerPts)) {
        const rRoll = seededRand();
        if (rRoll < 0.20) land.hills.push({ x: tx, y: ty, r: 28 + seededRand() * 52, shade: seededRand() > 0.5 ? '#2d5a27' : '#3a6b33', hasPeak: seededRand() < 0.45 });
        else if (rRoll < 0.30) land.rocks.push({ x: tx, y: ty, r: 9 + seededRand() * 15, shade: seededRand() > 0.5 ? '#64748b' : '#475569' });
        else if (rRoll < 0.34) land.huts.push({ x: tx, y: ty, size: 8 + seededRand() * 5, angle: seededRand() * Math.PI });
        else land.trees.push({ x: tx, y: ty, r: 10 + seededRand() * 13, isPalm: seededRand() < 0.55, color: seededRand() > 0.45 ? '#18421f' : '#26602e' });
      }
    }
  }
  bakeLandmassOffscreenCache(land);
};

function bakeLandmassOffscreenCache(land) {
  try {
    const rawW = (land.bbox.maxX - land.bbox.minX), rawH = (land.bbox.maxY - land.bbox.minY);
    const maxTex = 2048;
    const scale = Math.min(1.0, maxTex / Math.max(1, rawW), maxTex / Math.max(1, rawH));
    const off = document.createElement('canvas');
    off.width = Math.max(64, Math.ceil(rawW * scale));
    off.height = Math.max(64, Math.ceil(rawH * scale));
    const octx = off.getContext('2d');

    octx.save();
    octx.scale(scale, scale);
    octx.translate(-land.bbox.minX, -land.bbox.minY);
    octx.lineJoin = 'round'; octx.lineCap = 'round';

    const pts = land.renderPts;
    octx.fillStyle = land.isGhostIsle ? '#111827' : '#ebd096';
    octx.strokeStyle = land.isGhostIsle ? '#065f46' : '#c7a05c';
    octx.lineWidth = 14;
    octx.beginPath();
    pts.forEach((p, i) => i === 0 ? octx.moveTo(p[0], p[1]) : octx.lineTo(p[0], p[1]));
    octx.closePath(); octx.fill(); octx.stroke();

    if (!land.isGhostIsle) {
      octx.save(); octx.clip();
      octx.fillStyle = '#2d6a31'; octx.fill();
      if (land.innerPts) {
        octx.fillStyle = '#1e4d23'; octx.beginPath();
        land.innerPts.forEach((p, i) => i === 0 ? octx.moveTo(p[0], p[1]) : octx.lineTo(p[0], p[1]));
        octx.closePath(); octx.fill();
      }
      if (land.highlandPts) {
        octx.fillStyle = '#153819'; octx.beginPath();
        land.highlandPts.forEach((p, i) => i === 0 ? octx.moveTo(p[0], p[1]) : octx.lineTo(p[0], p[1]));
        octx.closePath(); octx.fill();
      }
      for (const h of land.hills) {
        octx.fillStyle = h.shade; octx.beginPath(); octx.arc(h.x, h.y, h.r, 0, Math.PI * 2); octx.fill();
        if (h.hasPeak) {
          octx.fillStyle = '#475569'; octx.beginPath();
          octx.moveTo(h.x, h.y - h.r * 0.65); octx.lineTo(h.x + h.r * 0.55, h.y + h.r * 0.45); octx.lineTo(h.x - h.r * 0.55, h.y + h.r * 0.45);
          octx.closePath(); octx.fill();
        }
      }
      for (const rk of land.rocks) {
        octx.fillStyle = rk.shade; octx.beginPath(); octx.ellipse(rk.x, rk.y, rk.r, rk.r * 0.7, 0.4, 0, Math.PI * 2); octx.fill();
      }
      for (const tObj of land.trees) {
        octx.fillStyle = 'rgba(0, 15, 5, 0.28)'; octx.beginPath(); octx.arc(tObj.x + 3, tObj.y + 3, tObj.r, 0, Math.PI * 2); octx.fill();
        if (tObj.isPalm) {
          octx.fillStyle = '#367c39';
          for (let f = 0; f < 5; f++) {
            const ang = (f / 5) * Math.PI * 2;
            octx.beginPath(); octx.ellipse(tObj.x + Math.cos(ang) * tObj.r * 0.5, tObj.y + Math.sin(ang) * tObj.r * 0.5, tObj.r * 0.65, tObj.r * 0.25, ang, 0, Math.PI * 2); octx.fill();
          }
          octx.fillStyle = '#78350f'; octx.beginPath(); octx.arc(tObj.x, tObj.y, tObj.r * 0.2, 0, Math.PI * 2); octx.fill();
        } else {
          octx.fillStyle = tObj.color; octx.beginPath(); octx.arc(tObj.x, tObj.y, tObj.r, 0, Math.PI * 2); octx.fill();
          octx.fillStyle = '#36753b'; octx.beginPath(); octx.arc(tObj.x - tObj.r * 0.25, tObj.y - tObj.r * 0.25, tObj.r * 0.45, 0, Math.PI * 2); octx.fill();
        }
      }
      octx.restore();
    }
    octx.restore();
    land.cachedCanvas = off;
  } catch (e) { land.cachedCanvas = null; }
}

window.findClosestCoastPointAndSeaAngle = function(wx, wy) {
  let bestDist = Infinity, bestPt = [wx, wy], bestLand = null, bestSegDx = 1, bestSegDy = 0;
  for (const land of LANDMASSES) {
    if (land.isGhostIsle) continue;
    const pts = land.renderPts || land.pts;
    for (let i = 0; i < pts.length; i++) {
      const p0 = pts[i], p1 = pts[(i + 1) % pts.length];
      if ((p0[0] <= 15 || p0[0] >= WORLD_W - 15 || p0[1] <= 15 || p0[1] >= WORLD_H - 15) &&
          (p1[0] <= 15 || p1[0] >= WORLD_W - 15 || p1[1] <= 15 || p1[1] >= WORLD_H - 15)) continue;
      const vx = p1[0] - p0[0], vy = p1[1] - p0[1];
      const lenSq = vx * vx + vy * vy;
      let tProj = lenSq > 0 ? ((wx - p0[0]) * vx + (wy - p0[1]) * vy) / lenSq : 0;
      tProj = Math.max(0, Math.min(1, tProj));
      const cx = p0[0] + tProj * vx, cy = p0[1] + tProj * vy;
      const d = Math.hypot(wx - cx, wy - cy);
      if (d < bestDist) { bestDist = d; bestPt = [cx, cy]; bestLand = land; bestSegDx = vx; bestSegDy = vy; }
    }
  }
  if (!bestLand) return { x: wx, y: wy, seaAngle: Math.PI / 2 };

  const segLen = Math.max(1, Math.hypot(bestSegDx, bestSegDy));
  let nx = -bestSegDy / segLen, ny = bestSegDx / segLen;
  if (nx * (bestPt[0] - bestLand.cx) + ny * (bestPt[1] - bestLand.cy) < 0) { nx = -nx; ny = -ny; }
  if (pointInPolygon(bestPt[0] + nx * 85, bestPt[1] + ny * 85, bestLand.pts)) { nx = -nx; ny = -ny; }

  return { x: Math.round(bestPt[0] + nx * 18), y: Math.round(bestPt[1] + ny * 18), seaAngle: Math.atan2(ny, nx) };
};

window.alignPortsAndVillagesToCoastline = function() {
  if (!window._portsAndVillagesAligned) {
    window._portsAndVillagesAligned = true;
    PORTS.forEach((p, idx) => {
      const aligned = findClosestCoastPointAndSeaAngle(p.x, p.y);
      p.x = aligned.x; p.y = aligned.y;
      p.coastRotation = aligned.seaAngle - Math.PI / 2;
      p.seaAngle = aligned.seaAngle;
      p.beamAngle = (idx * 1.1) % (Math.PI * 2);
      p.openWorldX = p.x; p.openWorldY = p.y;
      p.openWorldRot = p.coastRotation; p.openWorldSeaAng = p.seaAngle;
    });
    FISHING_VILLAGES.forEach(fv => {
      const aligned = findClosestCoastPointAndSeaAngle(fv.x, fv.y);
      fv.x = aligned.x; fv.y = aligned.y;
      fv.coastRotation = aligned.seaAngle - Math.PI / 2;
      fv.seaAngle = aligned.seaAngle;
    });
    if (typeof BASE_PLOTS !== 'undefined') {
      BASE_PLOTS.forEach(bp => {
        const aligned = findClosestCoastPointAndSeaAngle(bp.x, bp.y);
        bp.x = aligned.x; bp.y = aligned.y;
        bp.coastRotation = aligned.seaAngle - Math.PI / 2;
        bp.seaAngle = aligned.seaAngle;
      });
    }
  }

  PORTS.forEach((p, idx) => {
    if (p.hasLighthouse) {
      const sideSign = (idx % 2 === 0) ? 1 : -1;
      const sideAng = (p.seaAngle || 0) + sideSign * 0.92;
      p.lighthouseX = Math.round(p.x + Math.cos(sideAng) * 96);
      p.lighthouseY = Math.round(p.y + Math.sin(sideAng) * 96);
      p.maxLighthouseHp = 680;
      p.lighthouseHp = 680;
    } else {
      p.lighthouseHp = 0; p.maxLighthouseHp = 0;
    }
  });
};

window.getCollidingCoralReef = function(x, y, pad = 0) {
  const wb = getActiveWorldBounds();
  for (const rf of wb.reefs) {
    const rx = rf.rx + pad, ry = rf.ry + pad;
    const dx = x - rf.x, dy = y - rf.y;
    if (Math.abs(dx) > rx + 40 || Math.abs(dy) > ry + 40) continue;
    const cos = Math.cos(-rf.angle), sin = Math.sin(-rf.angle);
    const lx = dx * cos - dy * sin, ly = dx * sin + dy * cos;
    if ((lx * lx) / (rx * rx) + (ly * ly) / (ry * ry) <= 1.0) return rf;
  }
  return null;
};

window.hasShoalPilotRadar = function() {
  if (!window.game || !window.player) return false;
  const mods = getOfficerModifiers();
  return (mods.shoalRadar || 0) > 0 || hasCaptainPerk('perk_klabautermann_tea');
};

window.getActiveMissionTargetCoords = function() {
  if (!window.game) return null;
  if (game.activePassenger) {
    const tp = PORTS.find(p => p.id === game.activePassenger.destPortId);
    if (tp) return { x: tp.x, y: tp.y, label: tp.name };
  }
  if (!game.activeMission) return null;
  const ms = game.activeMission;
  if (ms.targetPortId) {
    const tp = PORTS.find(p => p.id === ms.targetPortId);
    if (tp) return { x: tp.x, y: tp.y, label: tp.name };
  }
  if (ms.type === 'hunt' || ms.type === 'capture_only') {
    const s = ships.find(sh => sh.isMissionTarget);
    if (s) return { x: s.x, y: s.y, label: s.name };
  }
  if (ms.type === 'rescue') {
    const fl = flotsam.find(f => f.isMissionRescue);
    if (fl) return { x: fl.x, y: fl.y, label: ms.targetPortName || 'SOS' };
  }
  return null;
};

// ============================================================================
// OZEAN-WELLEN, MEERESSTRÖMUNGEN & STRUDEL
// ============================================================================
window.drawOceanWavesAndGlint = function(ctx, camLeft, camTop, viewW, viewH) {
  const tVal = (game.time || 0) * 0.022;
  const tod = ((game.timeOfDay || 0.35) % 1 + 1) % 1;
  const isDawnDusk = (tod > 0.20 && tod < 0.32) || (tod > 0.70 && tod < 0.84);
  const isNight = tod >= 0.83 || tod <= 0.20;

  const cell = 220;
  const startX = Math.floor(camLeft / cell) * cell;
  const startY = Math.floor(camTop / cell) * cell;

  ctx.save();
  ctx.lineWidth = 1.8;
  for (let gx = startX; gx < camLeft + viewW + cell; gx += cell) {
    for (let gy = startY; gy < camTop + viewH + cell; gy += cell) {
      const hash = Math.sin(gx * 0.013 + gy * 0.017) * 43758.5453;
      const frac = hash - Math.floor(hash);
      const driftX = Math.cos(wind.angle) * ((tVal * 16) % cell);
      const driftY = Math.sin(wind.angle) * ((tVal * 16) % cell);
      const wx = gx + frac * 140 + driftX;
      const wy = gy + ((frac * 7.3) % 1) * 140 + driftY;
      const waveAlpha = 0.05 + 0.04 * Math.sin(tVal + frac * 12);

      ctx.strokeStyle = isNight ? `rgba(125, 211, 252, ${waveAlpha})` : `rgba(165, 243, 252, ${waveAlpha * 1.35})`;
      ctx.beginPath();
      ctx.moveTo(wx - 22, wy);
      ctx.quadraticCurveTo(wx, wy - 6 * Math.sin(tVal + frac * 6), wx + 22, wy);
      ctx.stroke();

      const glint = Math.sin(tVal * 2.0 + frac * 31.4);
      if (glint > 0.93) {
        ctx.fillStyle = isDawnDusk ? 'rgba(253, 224, 71, 0.45)' : (isNight ? 'rgba(224, 242, 254, 0.32)' : 'rgba(255, 255, 255, 0.38)');
        ctx.beginPath(); ctx.arc(wx + 6, wy - 3, 2.2 + (glint - 0.93) * 18, 0, Math.PI * 2); ctx.fill();
      }
    }
  }
  ctx.restore();
};

// Zeichnet fließende türkisblaue Strömungsbänder auf dem Meer
window.drawOceanCurrentsWorld = function(ctx, camLeft, camTop, viewW, viewH) {
  if (window.game && game.isMultiplayer && game.mpMode === 'deathmatch') return;
  if (typeof OCEAN_CURRENTS === 'undefined') return;
  const animOffset = ((game.time || 0) * 1.4) % 240;

  ctx.save();
  for (const cur of OCEAN_CURRENTS) {
    const minX = Math.min(cur.x1, cur.x2) - cur.width;
    const maxX = Math.max(cur.x1, cur.x2) + cur.width;
    const minY = Math.min(cur.y1, cur.y2) - cur.width;
    const maxY = Math.max(cur.y1, cur.y2) + cur.width;
    if (maxX < camLeft || minX > camLeft + viewW || maxY < camTop || minY > camTop + viewH) continue;

    const dx = cur.x2 - cur.x1, dy = cur.y2 - cur.y1;
    const len = Math.hypot(dx, dy);
    const ang = Math.atan2(dy, dx);
    const ux = dx / len, uy = dy / len;
    const nx = -uy, ny = ux;

    ctx.strokeStyle = 'rgba(56, 189, 248, 0.14)';
    ctx.lineWidth = 2.2;
    for (let lane = -1; lane <= 1; lane++) {
      const lOff = lane * (cur.width * 0.24);
      for (let d = animOffset; d < len - 60; d += 240) {
        const px = cur.x1 + ux * d + nx * lOff;
        const py = cur.y1 + uy * d + ny * lOff;
        if (px < camLeft - 80 || px > camLeft + viewW + 80 || py < camTop - 80 || py > camTop + viewH + 80) continue;
        if (getCollidingLand(px, py)) continue;

        ctx.save();
        ctx.translate(px, py);
        ctx.rotate(ang);
        ctx.beginPath();
        ctx.moveTo(-28, 0); ctx.lineTo(24, 0);
        ctx.moveTo(14, -7); ctx.lineTo(25, 0); ctx.lineTo(14, 7);
        ctx.stroke();
        ctx.restore();
      }
    }
  }
  ctx.restore();
};

window.drawWhirlpools = function(ctx, camLeft, camTop, viewW, viewH) {
  const list = window.whirlpools || [];
  if (list.length === 0) return;
  const pilotActive = hasShoalPilotRadar();

  for (const wp of list) {
    if (wp.x + wp.r * 1.4 < camLeft || wp.x - wp.r * 1.4 > camLeft + viewW ||
        wp.y + wp.r * 1.4 < camTop || wp.y - wp.r * 1.4 > camTop + viewH) continue;

    const fade = Math.min(1, wp.life / 180, (wp.maxLife - wp.life + 60) / 180);
    ctx.save();
    ctx.translate(wp.x, wp.y);
    ctx.globalAlpha = fade;

    const outerGrad = ctx.createRadialGradient(0, 0, wp.r * 0.06, 0, 0, wp.r);
    outerGrad.addColorStop(0, 'rgba(2, 6, 18, 0.95)');
    outerGrad.addColorStop(0.28, 'rgba(6, 42, 64, 0.82)');
    outerGrad.addColorStop(0.68, 'rgba(20, 184, 166, 0.32)');
    outerGrad.addColorStop(1, 'rgba(6, 34, 53, 0)');
    ctx.fillStyle = outerGrad;
    ctx.beginPath(); ctx.arc(0, 0, wp.r, 0, Math.PI * 2); ctx.fill();

    ctx.save();
    ctx.rotate(wp.spinAngle || 0);
    for (let arm = 0; arm < 4; arm++) {
      ctx.save();
      ctx.rotate((arm / 4) * Math.PI * 2);
      ctx.strokeStyle = 'rgba(224, 242, 254, 0.48)'; ctx.lineWidth = 3.2;
      ctx.beginPath();
      for (let s = 0; s <= 22; s++) {
        const frac = s / 22;
        const rad = wp.r * (0.10 + frac * 0.85);
        const ang = frac * 3.4;
        if (s === 0) ctx.moveTo(Math.cos(ang) * rad, Math.sin(ang) * rad);
        else ctx.lineTo(Math.cos(ang) * rad, Math.sin(ang) * rad);
      }
      ctx.stroke();
      ctx.restore();
    }
    ctx.restore();

    if (pilotActive) {
      ctx.strokeStyle = 'rgba(251, 191, 36, 0.85)'; ctx.lineWidth = 2.5; ctx.setLineDash([10, 8]);
      ctx.beginPath(); ctx.arc(0, 0, wp.r, 0, Math.PI * 2); ctx.stroke(); ctx.setLineDash([]);
    }
    ctx.restore();
  }
};

// ============================================================================
// KOMPLETT NEU GESTALTETE ORGANISCHE KORALLENRIFFE!
// ============================================================================
window.drawCoralReef = function(ctx, rf) {
  const pilotActive = hasShoalPilotRadar();
  ctx.save();
  ctx.translate(rf.x, rf.y);
  ctx.rotate(rf.angle);

  const surf = Math.sin((game.time || 0) * 0.045 + rf.x * 0.01) * 4.5;

  // 1. Weicher türkisgrüner Unterwasser-Lagunenschein
  const reefGrad = ctx.createRadialGradient(0, 0, rf.ry * 0.2, 0, 0, rf.rx * 1.15);
  reefGrad.addColorStop(0, 'rgba(45, 212, 191, 0.46)');
  reefGrad.addColorStop(0.65, 'rgba(20, 184, 166, 0.24)');
  reefGrad.addColorStop(1, 'rgba(13, 148, 136, 0)');
  ctx.fillStyle = reefGrad;
  ctx.beginPath();
  ctx.ellipse(0, 0, rf.rx + 26 + surf, rf.ry + 22 + surf * 0.5, 0, 0, Math.PI * 2);
  ctx.fill();

  // 2. Kalkstein-Riffbank (organische gelappte Kontur unter der Wasseroberfläche)
  ctx.fillStyle = 'rgba(214, 195, 148, 0.36)';
  ctx.beginPath();
  for (let a = 0; a < Math.PI * 2; a += 0.35) {
    const lobe = 0.78 + 0.18 * Math.sin(a * 5 + rf.x);
    const px = Math.cos(a) * rf.rx * lobe;
    const py = Math.sin(a) * rf.ry * lobe;
    if (a === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.fill();

  // 3. Verzweigte Korallenstöcke (Geweih-, Fächer- & Hirnkorallen)
  const palette = ['#fb7185', '#f97316', '#e879f9', '#facc15', '#2dd4bf', '#f43f5e'];
  for (let i = -4; i <= 4; i++) {
    const seed = Math.abs(i * 17 + Math.round(rf.x));
    const cx = i * (rf.rx * 0.18) + Math.sin(seed) * 9;
    const cy = Math.sin(i * 1.7 + rf.y * 0.01) * (rf.ry * 0.44);
    const col = palette[seed % palette.length];

    // Dunkler Riffschatten
    ctx.fillStyle = 'rgba(15, 23, 42, 0.35)';
    ctx.beginPath(); ctx.arc(cx + 2, cy + 2, 11 + (seed % 5), 0, Math.PI * 2); ctx.fill();

    // Verästelte Geweihkorallen-Arme
    ctx.strokeStyle = col;
    ctx.lineWidth = 3.2;
    ctx.lineCap = 'round';
    for (let b = 0; b < 5; b++) {
      const bAng = (b / 5) * Math.PI * 2 + (seed % 3) * 0.4;
      const bLen = 8 + (seed + b * 3) % 9;
      const ex = cx + Math.cos(bAng) * bLen;
      const ey = cy + Math.sin(bAng) * bLen;
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.lineTo(ex, ey);
      // Kleine Gabelspitzen
      ctx.lineTo(ex + Math.cos(bAng + 0.5) * 4.5, ey + Math.sin(bAng + 0.5) * 4.5);
      ctx.moveTo(ex, ey);
      ctx.lineTo(ex + Math.cos(bAng - 0.5) * 4.5, ey + Math.sin(bAng - 0.5) * 4.5);
      ctx.stroke();
    }

    // Heller Korallenkern
    ctx.fillStyle = '#fef3c7';
    ctx.globalAlpha = 0.65;
    ctx.beginPath(); ctx.arc(cx, cy, 3.0, 0, Math.PI * 2); ctx.fill();
    ctx.globalAlpha = 1.0;
  }

  // 4. Schäumende weiße Brandungsbögen, die sich am Riffkamm brechen!
  ctx.strokeStyle = `rgba(248, 250, 252, ${0.52 + Math.sin((game.time || 0) * 0.06 + rf.x) * 0.18})`;
  ctx.lineWidth = 2.6;
  ctx.beginPath();
  ctx.ellipse(0, -rf.ry * 0.12, rf.rx * 0.86 + surf * 0.6, rf.ry * 0.72 + surf * 0.3, 0, -Math.PI * 0.85, -Math.PI * 0.15);
  ctx.stroke();
  ctx.beginPath();
  ctx.ellipse(0, rf.ry * 0.12, rf.rx * 0.78 - surf * 0.4, rf.ry * 0.68, 0, Math.PI * 0.18, Math.PI * 0.82);
  ctx.stroke();

  if (pilotActive) {
    ctx.strokeStyle = 'rgba(251, 191, 36, 0.92)';
    ctx.lineWidth = 3.0;
    ctx.setLineDash([12, 8]);
    ctx.beginPath();
    ctx.ellipse(0, 0, rf.rx + 8, rf.ry + 8, 0, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  ctx.restore();

  // Aufrechte 2.5D-Korallenriff-Stöcke auf der Riffbank ergänzen
  drawWorldSpriteUpright(ctx, 'coral_cluster', rf.x - rf.rx * 0.25, rf.y, 105, 105, 0.62, false);
  drawWorldSpriteUpright(ctx, 'coral_cluster', rf.x + rf.rx * 0.25, rf.y + 6, 95, 95, 0.62, true);
};

// ============================================================================
// WRACKS, COMBAT-TEXTE & NATURWUNDER DER ENTDECKER-GILDE
// ============================================================================
window.sinkingWrecks = [];
window.worldCombatTexts = [];

window.spawnSinkingWreck = function(ship) {
  if (!ship) return;
  window.sinkingWrecks.push({
    x: ship.x, y: ship.y, angle: ship.angle,
    length: ship.length || 64, width: ship.width || 22,
    hullColor: ship.hullColor || '#4a2e1b', isGhost: !!ship.isGhost,
    life: 480, maxLife: 480
  });
  if (window.sinkingWrecks.length > 25) window.sinkingWrecks.shift();
};

window.spawnWorldCombatText = function(x, y, text, color = '#fde047', size = 14) {
  window.worldCombatTexts.push({
    x: x + (Math.random() - 0.5) * 18, y: y - 14 + (Math.random() - 0.5) * 10,
    vy: -0.75, text, color, size, life: 58, maxLife: 58
  });
  if (window.worldCombatTexts.length > 60) window.worldCombatTexts.shift();
};

window.updateAndDrawWrecks = function(ctx, isPaused = false) {
  for (let i = window.sinkingWrecks.length - 1; i >= 0; i--) {
    const wr = window.sinkingWrecks[i];
    if (!isPaused) wr.life--;
    if (wr.life <= 0) { window.sinkingWrecks.splice(i, 1); continue; }
    const alpha = Math.min(1, wr.life / 160);
    const sinkScale = 0.70 + 0.30 * (wr.life / wr.maxLife);
    ctx.save();
    ctx.globalAlpha = alpha * 0.92;
    const sz = Math.max(68, (wr.length || 68) * 1.15) * sinkScale;
    if (!drawWorldSpriteUpright(ctx, 'shipwreck', wr.x, wr.y, sz, sz, 0.65, (i % 2 === 1))) {
      ctx.translate(wr.x, wr.y); ctx.rotate(wr.angle); ctx.scale(sinkScale, sinkScale);
      ctx.fillStyle = wr.isGhost ? '#042f2e' : '#291709';
      ctx.beginPath(); ctx.ellipse(0, 0, wr.length * 0.45, wr.width * 0.45, 0, 0, Math.PI * 2); ctx.fill();
    }
    ctx.restore();
  }
};

window.updateAndDrawWorldCombatTexts = function(ctx, isPaused = false) {
  for (let i = window.worldCombatTexts.length - 1; i >= 0; i--) {
    const ft = window.worldCombatTexts[i];
    if (!isPaused) { ft.y += ft.vy; ft.life--; }
    if (ft.life <= 0) { window.worldCombatTexts.splice(i, 1); continue; }
    ctx.save();
    ctx.globalAlpha = Math.min(1, ft.life / 20);
    ctx.font = `bold ${ft.size}px sans-serif`; ctx.textAlign = 'center';
    ctx.fillStyle = 'rgba(0,0,0,0.88)'; drawCanvasIconLabel(ctx, ft.text, ft.x, ft.y, ft.size + 2);
    ctx.restore();
  }
};

window.drawDiscoveryWondersWorld = function(ctx, camLeft, camTop, viewW, viewH) {
  if ((game.isMultiplayer && game.mpMode === 'deathmatch') || typeof DISCOVERY_WONDERS === 'undefined') return;
  const foundMap = (game.discoveries && game.discoveries.found) || {};
  const tiltInv = 1 / (window.ISO_TILT_Y || 0.62);
  const wonderSpriteMap = {
    disc_flamingos: 'wonder_flamingos',
    disc_blue_hole: 'wonder_bluehole',
    disc_pelée_volcano: 'volcano_peak',
    disc_tulum_cliffs: 'maya_temple',
    disc_biolum_lagoon: 'wonder_bluehole',
    disc_whale_breach: 'wonder_whale',
    disc_spanish_hulk: 'shipwreck',
    disc_emerald_arch: 'skull_arch'
  };

  for (const dw of DISCOVERY_WONDERS) {
    if (dw.x + 180 < camLeft || dw.x - 180 > camLeft + viewW ||
        dw.y + 180 < camTop || dw.y - 180 > camTop + viewH) continue;

    const isFound = !!foundMap[dw.id];
    const shimmer = 0.45 + 0.35 * Math.sin((game.time || 0) * 0.08 + dw.x);

    ctx.save();
    ctx.translate(dw.x, dw.y);
    ctx.fillStyle = isFound ? 'rgba(46, 204, 113, 0.24)' : `rgba(253, 224, 71, ${shimmer * 0.35})`;
    ctx.beginPath(); ctx.arc(0, 0, 38, 0, Math.PI * 2); ctx.fill();
    ctx.restore();

    const sprKey = wonderSpriteMap[dw.id];
    if (!sprKey || !drawWorldSpriteUpright(ctx, sprKey, dw.x, dw.y, 108, 108, 0.68)) {
      ctx.save(); ctx.translate(dw.x, dw.y); ctx.scale(1, tiltInv);
      ctx.font = '22px sans-serif'; ctx.textAlign = 'center';
      drawCanvasIconLabel(ctx, dw.icon, 0, 6, 22);
      ctx.restore();
    }

    if (isFound) {
      ctx.save(); ctx.translate(dw.x, dw.y - 58); ctx.scale(1, tiltInv);
      ctx.shadowColor = '#000'; ctx.shadowBlur = 4;
      ctx.fillStyle = '#a7f3d0'; ctx.font = 'bold 12px sans-serif'; ctx.textAlign = 'center';
      ctx.fillText(`✓ ${tr(dw.name_de, dw.name_en)}`, 0, 0);
      ctx.restore();
    }
  }
};

window.drawLandmassDetailed = function(ctx, land) {
  if (land.isGhostIsle && (!game || game.worldMode !== 'mythology')) return;
  const pts = land.renderPts || land.pts;
  const surfPulse = Math.sin(game.time * 0.045) * 7;
  const pilotActive = hasShoalPilotRadar();

  ctx.save();
  ctx.lineJoin = 'round'; ctx.lineCap = 'round';

  ctx.strokeStyle = land.isGhostIsle ? 'rgba(16, 185, 129, 0.24)' : 'rgba(20, 184, 166, 0.22)';
  ctx.lineWidth = 118 + surfPulse;
  ctx.beginPath(); pts.forEach((p, idx) => idx === 0 ? ctx.moveTo(p[0], p[1]) : ctx.lineTo(p[0], p[1])); ctx.closePath(); ctx.stroke();

  ctx.strokeStyle = land.isGhostIsle ? 'rgba(52, 211, 153, 0.35)' : 'rgba(45, 212, 191, 0.34)';
  ctx.lineWidth = 62 + surfPulse * 0.6; ctx.stroke();

  ctx.strokeStyle = 'rgba(240, 253, 250, 0.50)';
  ctx.lineWidth = 22 + surfPulse * 0.45; ctx.stroke();

  if (pilotActive && !land.isGhostIsle && land.shoalPts &&
      Math.hypot(player.x - land.cx, player.y - land.cy) < Math.max(land.bbox.maxX - land.bbox.minX, land.bbox.maxY - land.bbox.minY) + 950) {
    ctx.strokeStyle = 'rgba(251, 191, 36, 0.58)'; ctx.lineWidth = 2.5; ctx.setLineDash([14, 10]);
    ctx.beginPath(); land.shoalPts.forEach((p, idx) => idx === 0 ? ctx.moveTo(p[0], p[1]) : ctx.lineTo(p[0], p[1])); ctx.closePath(); ctx.stroke();
    ctx.setLineDash([]);
  }

  if (land.cachedCanvas) {
    ctx.drawImage(land.cachedCanvas, land.bbox.minX, land.bbox.minY, land.bbox.maxX - land.bbox.minX, land.bbox.maxY - land.bbox.minY);
  }
  ctx.restore();

  // Aufrechte 2.5D-Natur-Sprites (Palmenhaine, Urwaldbäume, Felsenklippen & Vulkangipfel) auf sichtbaren Inseln!
  if (!land.isGhostIsle && window.PROPS_SPRITE_SHEET && window.PROPS_SPRITE_SHEET.loaded) {
    if (!land.props25d) {
      const list = [];
      (land.hills || []).slice(0, 6).forEach((h, idx) => {
        if (h.hasPeak && idx === 0 && h.r > 52) list.push({ key: 'volcano_peak', x: h.x, y: h.y, sz: 118, flip: false });
        else if (idx % 2 === 0) list.push({ key: 'cliff_rocks', x: h.x, y: h.y, sz: 82, flip: idx % 4 === 0 });
      });
      (land.rocks || []).slice(0, 8).forEach((rk, idx) => {
        if (idx % 2 === 0) list.push({ key: 'cliff_rocks', x: rk.x, y: rk.y, sz: 62, flip: idx % 3 === 0 });
      });
      (land.trees || []).forEach((trObj, idx) => {
        if (idx % 5 === 0) {
          list.push({
            key: trObj.isPalm ? 'palm_cluster' : 'jungle_trees',
            x: trObj.x, y: trObj.y,
            sz: trObj.isPalm ? 76 : 72,
            flip: (idx % 2 === 1)
          });
        }
      });
      list.sort((a, b) => a.y - b.y);
      land.props25d = list;
    }
    for (const pr of land.props25d) {
      drawWorldSpriteUpright(ctx, pr.key, pr.x, pr.y, pr.sz, pr.sz, 0.76, pr.flip);
    }
  }
};

// ============================================================================
// WACHSENDE SPIELER-KOLONIE & KOMPLETTES AUSBLENDEN FREIER BAUPLÄTZE!
// ============================================================================
window.drawBasePlotsWorld = function(ctx, camLeft, camTop, viewW, viewH) {
  if ((game.isMultiplayer && game.mpMode === 'deathmatch') || typeof BASE_PLOTS === 'undefined') return;
  const ownedPlotId = game.hideout && game.hideout.foundedPlotId;
  const night = isNightTime();
  const tiltInv = 1 / (window.ISO_TILT_Y || 0.62);

  for (const bp of BASE_PLOTS) {
    if (ownedPlotId && bp.id !== ownedPlotId) continue;
    if (bp.x + 280 < camLeft || bp.x - 280 > camLeft + viewW ||
        bp.y + 280 < camTop || bp.y - 280 > camTop + viewH) continue;

    const isOwned = (ownedPlotId === bp.id);
    ctx.save();
    ctx.translate(bp.x, bp.y);

    ctx.strokeStyle = isOwned ? '#a855f7' : 'rgba(251, 191, 36, 0.65)';
    ctx.fillStyle = isOwned ? 'rgba(168, 85, 247, 0.14)' : 'rgba(251, 191, 36, 0.07)';
    ctx.lineWidth = isOwned ? 2.8 : 1.8;
    ctx.setLineDash([9, 6]);
    ctx.beginPath(); ctx.arc(0, 0, isOwned ? 185 : 125, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    ctx.setLineDash([]);
    ctx.restore();

    if (!isOwned) {
      ctx.save();
      ctx.translate(bp.x, bp.y);
      ctx.scale(1, tiltInv);
      ctx.fillStyle = '#78350f'; ctx.fillRect(-3, -28, 6, 30);
      ctx.fillStyle = '#fde047'; ctx.strokeStyle = '#92400e'; ctx.lineWidth = 1.5;
      ctx.fillRect(3, -28, 18, 11); ctx.strokeRect(3, -28, 18, 11);
      ctx.fillStyle = '#fde68a'; ctx.font = 'bold 12px sans-serif'; ctx.textAlign = 'center';
      drawCanvasIconLabel(ctx, `🏗️ ${td(bp, 'name')}`, 0, -38, 15);
      ctx.restore();
    } else {
      const blds = (game.hideout && game.hideout.buildings) || {};
      const lvl = id => (blds[id] && blds[id].level) || 0;
      const seaAng = bp.seaAngle !== undefined ? bp.seaAngle : Math.PI / 2;
      const landAng = seaAng + Math.PI;
      const sideAng = seaAng + Math.PI / 2;
      const place = (alongLand, sideOff) => [
        bp.x + Math.cos(landAng) * alongLand + Math.cos(sideAng) * sideOff,
        bp.y + Math.sin(landAng) * alongLand + Math.sin(sideAng) * sideOff
      ];

      // Kai & Holzpier am Wasser
      ctx.save();
      ctx.translate(bp.x, bp.y);
      ctx.rotate(bp.coastRotation || 0);
      ctx.fillStyle = '#64748b'; ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 2;
      ctx.fillRect(-78, -22, 156, 32); ctx.strokeRect(-78, -22, 156, 32);
      ctx.fillStyle = '#5c3a21';
      ctx.fillRect(-13, 10, 26, 48); ctx.strokeRect(-13, 10, 26, 48);
      ctx.restore();

      // 2.5D-Gebäude-Sprites Y-sortiert auf der Kolonie-Bucht platzieren!
      const items = [];
      const addBld = (id, dLand, dSide, sz) => {
        if (lvl(id) <= 0) return;
        const [wx, wy] = place(dLand, dSide);
        const scaleLvl = 1 + (lvl(id) - 1) * 0.10;
        items.push({ id, wx, wy, w: sz * scaleLvl, h: sz * scaleLvl });
      };

      addBld('tobacco_coffee_estate', 96, 42, 92);
      addBld('herb_garden', 92, -38, 88);
      addBld('lumber_camp', 62, -78, 86);
      addBld('rum_distillery', 58, 76, 88);
      addBld('warehouse', 34, 0, 92);
      addBld('tavern', 28, -58, 86);
      addBld('powder_mill', 24, 62, 86);
      addBld('careenage', -18, 52, 88);
      if (lvl('coastal_fort') > 0) {
        addBld('coastal_fort', -22, -52, 92 + lvl('coastal_fort') * 6);
        if (lvl('coastal_fort') >= 2) addBld('coastal_fort', -26, 88, 82);
      }

      items.sort((a, b) => a.wy - b.wy);
      for (const it of items) {
        if (!drawWorldSpriteUpright(ctx, it.id, it.wx, it.wy, it.w, it.h, 0.72)) {
          ctx.save(); ctx.translate(it.wx, it.wy); ctx.scale(1, tiltInv);
          ctx.fillStyle = '#cbd5e1'; ctx.fillRect(-20, -28, 40, 26);
          ctx.restore();
        }
        if (it.id === 'rum_distillery') {
          const puff = ((game.time || 0) * 0.45) % 22;
          ctx.save(); ctx.translate(it.wx + 14, it.wy); ctx.scale(1, tiltInv);
          ctx.fillStyle = 'rgba(226, 232, 240, 0.55)';
          ctx.beginPath(); ctx.arc(0, -52 - puff * 0.8, 4 + puff * 0.22, 0, Math.PI * 2); ctx.fill();
          ctx.restore();
        }
        if (night && (it.id === 'tavern' || it.id === 'warehouse' || it.id === 'powder_mill')) {
          ctx.save(); ctx.translate(it.wx, it.wy); ctx.scale(1, tiltInv);
          ctx.fillStyle = 'rgba(253, 224, 71, 0.45)';
          ctx.beginPath(); ctx.arc(0, -16, 12, 0, Math.PI * 2); ctx.fill();
          ctx.restore();
        }
      }

      // Kolonie-Banner & Bastions-HP un-gestaucht über der Siedlung
      ctx.save();
      ctx.translate(bp.x, bp.y - 135);
      ctx.scale(1, tiltInv);
      const displayName = game.hideout.customBaseName || td(bp, 'name');
      ctx.fillStyle = '#f3e8ff'; ctx.font = 'bold 15px sans-serif'; ctx.textAlign = 'center';
      ctx.shadowColor = '#000'; ctx.shadowBlur = 6;
      drawCanvasIconLabel(ctx, `🏴‍☠️ ${displayName}`, 0, 0, 17);
      ctx.shadowBlur = 0;
      if (lvl('coastal_fort') > 0 && game.hideout.maxFortHp > 0) {
        const bw = 96;
        ctx.fillStyle = 'rgba(0,0,0,0.82)'; ctx.fillRect(-bw / 2, 8, bw, 7);
        ctx.fillStyle = '#38bdf8'; ctx.fillRect(-bw / 2, 8, bw * Math.max(0, (game.hideout.fortHp || 0) / game.hideout.maxFortHp), 7);
        ctx.strokeStyle = '#d4af37'; ctx.lineWidth = 1; ctx.strokeRect(-bw / 2, 8, bw, 7);
      }
      ctx.restore();
    }
  }
};

// ============================================================================
// LEUCHTTÜRME: TAGSÜBER AUS, NACHTS RUHIG & LANGSAM ROTIEREND (2.5D SPRITE)!
// ============================================================================
window.drawPortLighthouse = function(ctx, p) {
  if (!p.hasLighthouse || p.lighthouseX === undefined) return;
  const lx = p.lighthouseX, ly = p.lighthouseY;
  const alive = p.lighthouseHp > 0;
  const night = isNightTime();
  const tiltInv = 1 / (window.ISO_TILT_Y || 0.62);

  if (alive && night) {
    const beamRange = 1380;
    const spread = 0.22;
    const bAng = p.beamAngle || 0;
    ctx.save();
    ctx.translate(lx, ly);
    ctx.globalCompositeOperation = 'lighter';
    ctx.rotate(bAng);
    const grad = ctx.createRadialGradient(0, 0, 12, 0, 0, beamRange);
    grad.addColorStop(0, 'rgba(254, 240, 138, 0.52)');
    grad.addColorStop(0.38, 'rgba(253, 224, 71, 0.26)');
    grad.addColorStop(1, 'rgba(253, 224, 71, 0)');
    ctx.fillStyle = grad;
    ctx.beginPath(); ctx.moveTo(0, 0); ctx.arc(0, 0, beamRange, -spread, spread); ctx.closePath(); ctx.fill();
    ctx.restore();
  }

  if (!drawWorldSpriteUpright(ctx, 'lighthouse', lx, ly, 92, 92, 0.84)) {
    ctx.save(); ctx.translate(lx, ly);
    ctx.fillStyle = alive ? '#f8fafc' : '#334155';
    ctx.beginPath(); ctx.arc(0, 0, 16, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
  }

  if (alive && night) {
    ctx.save();
    ctx.translate(lx, ly);
    ctx.scale(1, tiltInv);
    ctx.fillStyle = '#fde047'; ctx.shadowColor = '#fde047'; ctx.shadowBlur = 22;
    ctx.beginPath(); ctx.arc(0, -56, 6.5, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
  }
};

window.drawGhostEnclaveWorld = function(ctx) {
  if (!game || game.worldMode !== 'mythology' || (game.isMultiplayer && game.mpMode === 'deathmatch')) return;
  const isGhostCap = !!(game.captain && game.captain.isGhostCaptain);
  const repCanEnter = getPlayerReputationTier(game.reputation || 0).canEnterEnclave || isGhostCap;
  const tiltInv = 1 / (window.ISO_TILT_Y || 0.62);

  ctx.save();
  ctx.translate(GHOST_ENCLAVE.x, GHOST_ENCLAVE.y);
  const pulse = Math.sin(game.time * 0.05) * 12;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const grad = ctx.createRadialGradient(0, 0, 20, 0, 0, 250 + pulse);
  grad.addColorStop(0, 'rgba(16, 185, 129, 0.36)');
  grad.addColorStop(0.6, 'rgba(6, 78, 59, 0.20)');
  grad.addColorStop(1, 'rgba(2, 44, 34, 0)');
  ctx.fillStyle = grad;
  ctx.beginPath(); ctx.arc(0, 0, 250 + pulse, 0, Math.PI * 2); ctx.fill();
  ctx.restore();

  ctx.strokeStyle = repCanEnter ? '#10b981' : '#ef4444';
  ctx.lineWidth = 2.8; ctx.setLineDash([12, 8]);
  ctx.beginPath(); ctx.arc(0, 0, 195, 0, Math.PI * 2); ctx.stroke(); ctx.setLineDash([]);
  ctx.restore();

  if (!drawWorldSpriteUpright(ctx, 'ghost_enclave', GHOST_ENCLAVE.x, GHOST_ENCLAVE.y, 185, 185, 0.76)) {
    ctx.save(); ctx.translate(GHOST_ENCLAVE.x, GHOST_ENCLAVE.y);
    ctx.fillStyle = '#022c22'; ctx.strokeStyle = '#34d399'; ctx.lineWidth = 2.5;
    ctx.beginPath(); ctx.arc(0, 0, 34, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    ctx.restore();
  }

  ctx.save();
  ctx.translate(GHOST_ENCLAVE.x, GHOST_ENCLAVE.y - 115);
  ctx.scale(1, tiltInv);
  ctx.fillStyle = '#6ee7b7'; ctx.font = 'bold 15px sans-serif'; ctx.textAlign = 'center';
  ctx.shadowColor = '#000'; ctx.shadowBlur = 6;
  drawCanvasIconLabel(ctx, `👻 ${td(GHOST_ENCLAVE, 'name')}`, 0, 0, 17);
  ctx.restore();
};

window.drawWololoShrineWorld = function(ctx) {
  if (!game || !game.wololoEnabled || game.isMultiplayer || typeof WOLOLO_SHRINE === 'undefined') return;
  const tiltInv = 1 / (window.ISO_TILT_Y || 0.62);
  const pulse = Math.sin((game.time || 0) * 0.06) * 10;

  ctx.save();
  ctx.translate(WOLOLO_SHRINE.x, WOLOLO_SHRINE.y);
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const grad = ctx.createRadialGradient(0, 0, 18, 0, 0, 220 + pulse);
  grad.addColorStop(0, 'rgba(250, 204, 21, 0.42)');
  grad.addColorStop(0.6, 'rgba(56, 189, 248, 0.18)');
  grad.addColorStop(1, 'rgba(15, 23, 42, 0)');
  ctx.fillStyle = grad;
  ctx.beginPath(); ctx.arc(0, 0, 220 + pulse, 0, Math.PI * 2); ctx.fill();
  ctx.restore();

  ctx.strokeStyle = '#ffd700'; ctx.lineWidth = 2.8; ctx.setLineDash([10, 7]);
  ctx.beginPath(); ctx.arc(0, 0, 185, 0, Math.PI * 2); ctx.stroke(); ctx.setLineDash([]);
  ctx.restore();

  if (!drawWorldSpriteUpright(ctx, 'wololo_shrine', WOLOLO_SHRINE.x, WOLOLO_SHRINE.y, 175, 175, 0.68)) {
    ctx.save(); ctx.translate(WOLOLO_SHRINE.x, WOLOLO_SHRINE.y);
    ctx.fillStyle = '#fef08a'; ctx.beginPath(); ctx.arc(0, 0, 32, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
  }

  ctx.save();
  ctx.translate(WOLOLO_SHRINE.x, WOLOLO_SHRINE.y - 108);
  ctx.scale(1, tiltInv);
  ctx.shadowColor = '#000'; ctx.shadowBlur = 6;
  ctx.fillStyle = '#fde047'; ctx.font = 'bold 15px sans-serif'; ctx.textAlign = 'center';
  drawCanvasIconLabel(ctx, `⛩️ ${td(WOLOLO_SHRINE, 'name')}`, 0, 0, 17);
  ctx.fillStyle = '#bae6fd'; ctx.font = 'bold 11.5px sans-serif';
  ctx.fillText('[Gratis Schiffe, Geister-Arsenal, Waren & Offiziere • Taste F]', 0, 18);
  ctx.restore();
};

// ============================================================================
// SCHIFFS-RENDERING (Mit Galionsfigur am Bug & sauberer Flagge am Flaggenstock!)
// ============================================================================
window.drawDetailedShip = function(ctx, ship, isPlayer, isEscort = false) {
  const halfL = ship.length / 2;
  const halfW = ship.width / 2;
  const ext = ship.cannonExtendPct || 0;
  const hullRatio = Math.max(0, ship.hull / Math.max(1, ship.maxHull));
  const sailHealth = Math.max(0, ship.sail / Math.max(1, ship.maxSail));
  const spd = ship.speed || 0;
  const cosA = Math.cos(ship.angle), sinA = Math.sin(ship.angle);
  const cosP = -sinA, sinP = cosA;
  const tiltInv = 1 / (window.ISO_TILT_Y || 0.62);
  const isGhostLook = !!(ship.isGhost || ship.hasGhostVisual || (isPlayer && (player.isGhostShip || player.hasGhostVisual || (game.captain && game.captain.isGhostCaptain))));

  const shipPt = (lx, ly, h = 0) => [
    ship.x + lx * cosA + ly * cosP,
    ship.y + lx * sinA + ly * sinP - h * tiltInv
  ];

  // 1. FLACHE WASSEREBENE (Enterschutz, Zielsektoren, Bugwelle & Wasserschatten)
  ctx.save();
  ctx.translate(ship.x, ship.y);
  ctx.rotate(ship.angle);

  if (ship.inBoardingLock || (ship.boardingInvulnTimer && ship.boardingInvulnTimer > 0)) {
    ctx.strokeStyle = '#38bdf8'; ctx.fillStyle = 'rgba(56, 189, 248, 0.14)';
    ctx.lineWidth = 2.8; ctx.setLineDash([8, 6]);
    ctx.beginPath(); ctx.ellipse(0, 0, halfL * 1.38, halfW * 1.85, 0, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    ctx.setLineDash([]);
  }

  if (isPlayer && ext > 0.25) {
    const range = 165 * ext;
    const anyPortReady = ship.portCannons.some((c, idx) => c <= 0 && (!ship.portCannonDamage || ship.portCannonDamage[idx] <= 0)) && ext > 0.75;
    const anyStbdReady = ship.stbdCannons.some((c, idx) => c <= 0 && (!ship.stbdCannonDamage || ship.stbdCannonDamage[idx] <= 0)) && ext > 0.75;
    ctx.fillStyle = anyPortReady ? 'rgba(46, 204, 113, 0.10)' : 'rgba(231, 76, 60, 0.04)';
    ctx.beginPath(); ctx.moveTo(-halfL * 0.55, -halfW); ctx.lineTo(-halfL * 0.85, -halfW - range); ctx.lineTo(halfL * 0.85, -halfW - range); ctx.lineTo(halfL * 0.55, -halfW); ctx.closePath(); ctx.fill();
    ctx.fillStyle = anyStbdReady ? 'rgba(46, 204, 113, 0.10)' : 'rgba(231, 76, 60, 0.04)';
    ctx.beginPath(); ctx.moveTo(-halfL * 0.55, halfW); ctx.lineTo(-halfL * 0.85, halfW + range); ctx.lineTo(halfL * 0.85, halfW + range); ctx.lineTo(halfL * 0.55, halfW); ctx.closePath(); ctx.fill();
  }

  if (spd > 0.18) {
    const wakeAlpha = Math.min(0.58, spd * 0.24);
    const waveLen = halfL * (0.75 + spd * 0.35);
    const waveSpread = halfW * (1.28 + spd * 0.28);
    ctx.strokeStyle = isGhostLook ? `rgba(110, 231, 183, ${wakeAlpha})` : `rgba(224, 242, 254, ${wakeAlpha})`;
    ctx.lineWidth = 2.2;
    ctx.beginPath();
    ctx.moveTo(halfL + 6, 0); ctx.quadraticCurveTo(halfL * 0.2, -waveSpread * 0.65, -waveLen * 0.65, -waveSpread);
    ctx.moveTo(halfL + 6, 0); ctx.quadraticCurveTo(halfL * 0.2, waveSpread * 0.65, -waveLen * 0.65, waveSpread);
    ctx.stroke();

    ctx.fillStyle = isGhostLook ? `rgba(52, 211, 153, ${wakeAlpha * 0.5})` : `rgba(240, 249, 255, ${wakeAlpha * 0.55})`;
    ctx.beginPath(); ctx.ellipse(-halfL - 8, 0, 9 + spd * 4, halfW * 0.42, 0, 0, Math.PI * 2); ctx.fill();
  }

  ctx.fillStyle = 'rgba(0, 8, 18, 0.56)';
  ctx.beginPath(); ctx.ellipse(-2, 4, halfL * 1.06, halfW * 1.16, 0, 0, Math.PI * 2); ctx.fill();
  ctx.restore();

  // 2. GESTAPELTER 2.5D-RUMPF + SPRITE-DECK (gibt dem Schiff in Isometrie echte Bordwandhöhe!)
  const hullHeight = Math.max(6, ship.width * 0.30);
  const sideHullCol = isGhostLook ? '#042f2e' : (isPlayer ? '#3e240e' : (isEscort ? '#172d4a' : ship.hullColor));
  const sprKey = isGhostLook
    ? (window.SHIP_SPRITE_SHEET.indexMap[ship.clsKey] >= 7 ? ship.clsKey : (ship.cannonsPerSide >= 10 ? 'dread_dutchman' : 'phantom_sloop'))
    : (window.SHIP_SPRITE_SHEET.indexMap[ship.clsKey] !== undefined ? ship.clsKey : 'sloop');
  const sprIdx = window.SHIP_SPRITE_SHEET.indexMap[sprKey] || 0;
  const sprScaleMap = { sloop: 0.46, brigantine: 0.56, flute: 0.62, corvette: 0.66, frigate: 0.74, galleon: 0.82, manowar: 0.90, phantom_sloop: 0.64, dread_dutchman: 0.86, ghostship: 0.90 };
  const wScaleMap = { sloop: 0.30, brigantine: 0.34, flute: 0.44, corvette: 0.35, frigate: 0.40, galleon: 0.48, manowar: 0.52, phantom_sloop: 0.36, dread_dutchman: 0.50, ghostship: 0.52 };

  const layers = 5;
  for (let l = 0; l < layers; l++) {
    const hStep = (l / layers) * hullHeight;
    ctx.save();
    ctx.translate(ship.x, ship.y - hStep * tiltInv);
    ctx.rotate(ship.angle);
    const isGunStripe = (l === 2 && !isGhostLook);
    ctx.fillStyle = l === layers - 1
      ? (isGhostLook ? '#064e3b' : '#6b4423')
      : (isGunStripe ? (isPlayer ? '#b47b32' : '#9a6b28') : sideHullCol);
    ctx.strokeStyle = isGhostLook ? '#10b981' : (l === 0 ? '#0f172a' : '#1c1007');
    ctx.lineWidth = l === 0 ? 2.4 : 1.1;
    ctx.beginPath();
    ctx.moveTo(halfL + 6, 0);
    ctx.quadraticCurveTo(halfL * 0.62, halfW * 1.02, -halfL * 0.85, halfW * 0.92);
    ctx.lineTo(-halfL, halfW * 0.70); ctx.lineTo(-halfL, -halfW * 0.70);
    ctx.lineTo(-halfL * 0.85, -halfW * 0.92);
    ctx.quadraticCurveTo(halfL * 0.62, -halfW * 1.02, halfL + 6, 0);
    ctx.closePath(); ctx.fill(); ctx.stroke();

    if (l === 2 && ext > 0.06) {
      const numCannons = ship.cannonsPerSide;
      const activePerSide = getShipMannedCannonsPerSide(ship, isPlayer);
      const usableLength = ship.length * 0.66;
      const portDmgArr = ship.portCannonDamage || [], stbdDmgArr = ship.stbdCannonDamage || [];
      for (let i = 0; i < activePerSide; i++) {
        const tPos = numCannons === 1 ? 0 : (i / (numCannons - 1)) - 0.5;
        const cx = tPos * usableLength;
        const pOut = ((portDmgArr[i] || 0) > 0 ? 1.5 : (ship.portCannons[i] <= 0 ? 6.6 : 2.8)) * ext;
        ctx.fillStyle = (portDmgArr[i] || 0) > 0 ? '#dc2626' : (isGhostLook ? '#34d399' : '#1e293b');
        ctx.fillRect(cx - 2.0, -halfW - pOut, 4.0, pOut + 1.5);
        const sOut = ((stbdDmgArr[i] || 0) > 0 ? 1.5 : (ship.stbdCannons[i] <= 0 ? 6.6 : 2.8)) * ext;
        ctx.fillStyle = (stbdDmgArr[i] || 0) > 0 ? '#dc2626' : (isGhostLook ? '#34d399' : '#1e293b');
        ctx.fillRect(cx - 2.0, halfW - 1.5, 4.0, sOut + 1.5);
      }
    }
    ctx.restore();
  }

  // Hochauflösendes Deck-Sprite (mit Fallback falls PNG noch lädt)
  ctx.save();
  ctx.translate(ship.x, ship.y - hullHeight * tiltInv);
  ctx.rotate(ship.angle);
  if (window.SHIP_SPRITE_SHEET && window.SHIP_SPRITE_SHEET.loaded) {
    const sh = window.SHIP_SPRITE_SHEET;
    const sx = (sprIdx % sh.cols) * sh.cellW;
    const sy = Math.floor(sprIdx / sh.cols) * sh.cellH;
    const drawW = ship.length / (0.88 * (sprScaleMap[sprKey] || 0.60));
    const drawH = ship.width / (0.88 * (wScaleMap[sprKey] || 0.36));
    ctx.drawImage(sh.img, sx, sy, sh.cellW, sh.cellH, -drawW / 2, -drawH / 2, drawW, drawH);
  } else {
    ctx.fillStyle = isGhostLook ? '#064e3b' : ((isPlayer || isEscort) ? '#a97947' : '#8c5322');
    ctx.beginPath();
    ctx.moveTo(halfL * 0.84, 0);
    ctx.quadraticCurveTo(halfL * 0.45, halfW * 0.76, -halfL * 0.82, halfW * 0.70);
    ctx.lineTo(-halfL * 0.82, -halfW * 0.70);
    ctx.quadraticCurveTo(halfL * 0.45, -halfW * 0.76, halfL * 0.84, 0);
    ctx.closePath(); ctx.fill();
  }

  if (isPlayer && player.specialEquipment === 'bow_chasers') {
    ctx.fillStyle = '#1f2937'; ctx.fillRect(halfL - 2, -2.5, 11, 5);
  }
  if (hullRatio < 0.75) {
    ctx.fillStyle = 'rgba(15, 10, 5, 0.85)';
    ctx.beginPath(); ctx.arc(halfL * 0.22, -halfW * 0.28, 3.5, 0, Math.PI * 2);
    if (hullRatio < 0.45) ctx.arc(-halfL * 0.25, halfW * 0.24, 4.8, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();

  // 3. 2.5D BUGSPRIET, GALIONSFIGUR & HECKLATERNEN
  const bowBase = shipPt(halfL * 0.68, 0, hullHeight);
  const bowTip  = shipPt(halfL + (hullRatio < 0.35 ? 12 : 24), 0, hullHeight + 5);
  ctx.strokeStyle = isGhostLook ? '#10b981' : '#4a2e1b'; ctx.lineWidth = 3.2;
  ctx.beginPath(); ctx.moveTo(bowBase[0], bowBase[1]); ctx.lineTo(bowTip[0], bowTip[1]); ctx.stroke();

  if (isPlayer && player.figurehead && window.FIGUREHEAD_DEFS) {
    const fhDef = FIGUREHEAD_DEFS.find(f => f.id === player.figurehead);
    if (fhDef) {
      const fhPt = shipPt(halfL + 10, 0, hullHeight + 1.5);
      ctx.fillStyle = fhDef.color || '#ffd700';
      ctx.beginPath(); ctx.arc(fhPt[0], fhPt[1], 3.8, 0, Math.PI * 2); ctx.fill();
    }
  }

  if (!isPlayer || ship.sailSetting > 0) {
    const foreStayTop = shipPt(halfL * 0.30, 0, hullHeight + halfW * 2.1);
    const tackPt = shipPt(halfL * 0.82, 0, hullHeight + 2);
    ctx.fillStyle = isGhostLook ? 'rgba(52, 211, 153, 0.52)' : 'rgba(248, 250, 252, 0.88)';
    ctx.strokeStyle = isGhostLook ? '#6ee7b7' : 'rgba(30,41,59,0.55)'; ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(bowTip[0], bowTip[1]);
    ctx.lineTo(foreStayTop[0], foreStayTop[1]);
    ctx.lineTo(tackPt[0], tackPt[1]);
    ctx.closePath(); ctx.fill(); ctx.stroke();
  }

  const nightGlow = isNightTime();
  [-halfW * 0.52, halfW * 0.52].forEach(ly => {
    const lp = shipPt(-halfL, ly, hullHeight + 4);
    ctx.save();
    ctx.fillStyle = isGhostLook ? '#34d399' : '#fde047';
    if (nightGlow || isGhostLook) { ctx.shadowColor = isGhostLook ? '#34d399' : '#fde047'; ctx.shadowBlur = 12; }
    ctx.beginPath(); ctx.arc(lp[0], lp[1], 2.6, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
  });

  // 4. 2.5D-MASTEN, WANTEN & GEBLÄHTE ISOMETRISCHE RAHSEGEL (von hinten nach vorne sortiert!)
  const mastCount = ship.cannonsPerSide >= 8 ? 3 : (ship.cannonsPerSide >= 4 ? 2 : 1);
  const sailColor = isGhostLook ? 'rgba(52, 211, 153, 0.66)' : ((isPlayer || isEscort) ? '#f8f9fa' : ship.sailColor);
  const billow = (isPlayer ? (0.12 + (ship.sailSetting / 3) * 0.88) : 0.86) * (6 + spd * 2.2);

  const masts = [];
  for (let m = 0; m < mastCount; m++) {
    const mt = mastCount === 1 ? 0.05 : ((m / (mastCount - 1)) - 0.5) * 0.56;
    const mx = mt * ship.length;
    const isMain = (mastCount === 3 && m === 1) || (mastCount === 2 && m === 1) || mastCount === 1;
    const mHeight = (ship.width * (isMain ? 2.55 : 2.15));
    const basePt = shipPt(mx, 0, hullHeight);
    masts.push({ mx, mHeight, basePt, screenY: basePt[1], isMain });
  }
  masts.sort((a, b) => a.screenY - b.screenY);

  for (const mObj of masts) {
    const { mx, mHeight, basePt } = mObj;
    const topPt = shipPt(mx, 0, hullHeight + mHeight);
    const portRail = shipPt(mx - 3, -halfW * 0.88, hullHeight);
    const stbdRail = shipPt(mx - 3, halfW * 0.88, hullHeight);
    const nestPt = shipPt(mx, 0, hullHeight + mHeight * 0.72);

    ctx.strokeStyle = isGhostLook ? 'rgba(52, 211, 153, 0.40)' : 'rgba(32, 20, 10, 0.52)';
    ctx.lineWidth = 1.15;
    ctx.beginPath();
    ctx.moveTo(portRail[0], portRail[1]); ctx.lineTo(nestPt[0], nestPt[1]);
    ctx.moveTo(stbdRail[0], stbdRail[1]); ctx.lineTo(nestPt[0], nestPt[1]);
    // Gewebte Wanten-Sprossen (Ratlines) für authentischen Segelschiff-Look
    for (let rl = 1; rl <= 3; rl++) {
      const rf = rl / 4;
      ctx.moveTo(portRail[0] * (1 - rf) + nestPt[0] * rf - 2, portRail[1] * (1 - rf) + nestPt[1] * rf);
      ctx.lineTo(portRail[0] * (1 - rf) + nestPt[0] * rf + 2, portRail[1] * (1 - rf) + nestPt[1] * rf);
      ctx.moveTo(stbdRail[0] * (1 - rf) + nestPt[0] * rf - 2, stbdRail[1] * (1 - rf) + nestPt[1] * rf);
      ctx.lineTo(stbdRail[0] * (1 - rf) + nestPt[0] * rf + 2, stbdRail[1] * (1 - rf) + nestPt[1] * rf);
    }
    ctx.stroke();

    ctx.strokeStyle = isGhostLook ? '#065f46' : '#3a2210'; ctx.lineWidth = 3.4;
    ctx.beginPath(); ctx.moveTo(basePt[0], basePt[1]); ctx.lineTo(topPt[0], topPt[1]); ctx.stroke();

    const tiers = mHeight > 44
      ? [{ hTop: mHeight * 0.56, hBot: mHeight * 0.16, w: halfW * 1.26 }, { hTop: mHeight * 0.93, hBot: mHeight * 0.60, w: halfW * 0.96 }]
      : [{ hTop: mHeight * 0.84, hBot: mHeight * 0.18, w: halfW * 1.22 }];

    for (const trSail of tiers) {
      const yPortTop = shipPt(mx, -trSail.w, hullHeight + trSail.hTop);
      const yStbdTop = shipPt(mx,  trSail.w, hullHeight + trSail.hTop);

      ctx.strokeStyle = isGhostLook ? '#10b981' : '#2e1a0c'; ctx.lineWidth = 2.2;
      ctx.beginPath(); ctx.moveTo(yPortTop[0], yPortTop[1]); ctx.lineTo(yStbdTop[0], yStbdTop[1]); ctx.stroke();

      if (!isPlayer || ship.sailSetting > 0) {
        const yPortBot = shipPt(mx + billow * 0.45, -trSail.w * 0.94, hullHeight + trSail.hBot);
        const yStbdBot = shipPt(mx + billow * 0.45,  trSail.w * 0.94, hullHeight + trSail.hBot);
        const bellyMid = shipPt(mx + billow, 0, hullHeight + (trSail.hTop + trSail.hBot) * 0.48);

        if (!isGhostLook) {
          const sGrad = ctx.createLinearGradient(yPortTop[0], yPortTop[1], bellyMid[0], bellyMid[1] + 10);
          sGrad.addColorStop(0, (isPlayer || isEscort) ? '#ffffff' : sailColor);
          sGrad.addColorStop(0.62, (isPlayer || isEscort) ? '#f1ebd8' : sailColor);
          sGrad.addColorStop(1, (isPlayer || isEscort) ? '#cbbba0' : 'rgba(180, 165, 140, 0.95)');
          ctx.fillStyle = sGrad;
        } else {
          ctx.fillStyle = sailColor;
        }
        ctx.strokeStyle = isGhostLook ? '#6ee7b7' : '#1e293b';
        ctx.lineWidth = 1.15;
        ctx.beginPath();
        ctx.moveTo(yPortTop[0], yPortTop[1]);
        ctx.lineTo(yStbdTop[0], yStbdTop[1]);
        ctx.quadraticCurveTo(bellyMid[0] + (yStbdBot[0] - bellyMid[0]) * 0.7, bellyMid[1] + (yStbdBot[1] - bellyMid[1]) * 0.7, yStbdBot[0], yStbdBot[1]);
        ctx.quadraticCurveTo(bellyMid[0], bellyMid[1] + 4, yPortBot[0], yPortBot[1]);
        ctx.closePath();
        ctx.fill(); ctx.stroke();

        // Dezent eingewebte Segelbahnen & Reffbänder für plastischen Tuch-Look
        const seamL = shipPt(mx + billow * 0.45, -trSail.w * 0.35, hullHeight + (trSail.hTop + trSail.hBot) * 0.5);
        const seamR = shipPt(mx + billow * 0.45,  trSail.w * 0.35, hullHeight + (trSail.hTop + trSail.hBot) * 0.5);
        ctx.strokeStyle = isGhostLook ? 'rgba(110, 231, 183, 0.28)' : 'rgba(71, 56, 38, 0.22)';
        ctx.lineWidth = 0.85;
        ctx.beginPath();
        ctx.moveTo((yPortTop[0] * 2 + yStbdTop[0]) / 3, (yPortTop[1] * 2 + yStbdTop[1]) / 3);
        ctx.quadraticCurveTo(seamL[0], seamL[1], (yPortBot[0] * 2 + yStbdBot[0]) / 3, (yPortBot[1] * 2 + yStbdBot[1]) / 3);
        ctx.moveTo((yPortTop[0] + yStbdTop[0] * 2) / 3, (yPortTop[1] + yStbdTop[1] * 2) / 3);
        ctx.quadraticCurveTo(seamR[0], seamR[1], (yPortBot[0] + yStbdBot[0] * 2) / 3, (yPortBot[1] + yStbdBot[1] * 2) / 3);
        ctx.stroke();

        if (sailHealth < 0.68 || isGhostLook) {
          const holePt = shipPt(mx + billow * 0.6, trSail.w * 0.22, hullHeight + (trSail.hTop + trSail.hBot) * 0.5);
          ctx.fillStyle = isGhostLook ? 'rgba(2, 44, 34, 0.82)' : 'rgba(15, 23, 42, 0.78)';
          ctx.beginPath(); ctx.arc(holePt[0], holePt[1], 3.8, 0, Math.PI * 2); ctx.fill();
        }
      }
    }

    ctx.fillStyle = isGhostLook ? '#064e3b' : '#2e1a0c';
    ctx.strokeStyle = isGhostLook ? '#34d399' : '#d4af37'; ctx.lineWidth = 1.1;
    ctx.beginPath(); ctx.ellipse(nestPt[0], nestPt[1], 4.5, 2.8, 0, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
  }

  // 5. WEHENDE HECKFLAGGE AM SCHRÄGEN 2.5D-FLAGGENSTOCK
  const flagCol = isGhostLook ? '#10b981' : (isPlayer
    ? (player.falseFlag && FACTIONS[player.falseFlag] ? FACTIONS[player.falseFlag].color : (game.allegiance && FACTIONS[game.allegiance] ? FACTIONS[game.allegiance].color : '#111827'))
    : (isEscort ? '#38bdf8' : (ship.falseFlag && FACTIONS[ship.falseFlag] ? FACTIONS[ship.falseFlag].color : ship.flagColor)));

  const poleBase = shipPt(-halfL, 0, hullHeight + 3);
  const poleTop  = shipPt(-halfL - 5, 0, hullHeight + 17);
  ctx.strokeStyle = '#78350f'; ctx.lineWidth = 1.8;
  ctx.beginPath(); ctx.moveTo(poleBase[0], poleBase[1]); ctx.lineTo(poleTop[0], poleTop[1]); ctx.stroke();

  const wAng = wind ? wind.angle : (ship.angle + Math.PI);
  const ripple = Math.sin((game.time || 0) * 0.12 + ship.x * 0.05) * 2.2;
  const fx = Math.cos(wAng) * 14, fy = Math.sin(wAng) * 14 * (window.ISO_TILT_Y || 0.62);
  ctx.fillStyle = flagCol; ctx.strokeStyle = 'rgba(255,255,255,0.65)'; ctx.lineWidth = 0.9;
  ctx.beginPath();
  ctx.moveTo(poleTop[0], poleTop[1]);
  ctx.lineTo(poleTop[0] + fx, poleTop[1] + fy + ripple);
  ctx.lineTo(poleTop[0] + fx * 0.82, poleTop[1] + fy + 4 + ripple * 0.5);
  ctx.lineTo(poleTop[0] + fx, poleTop[1] + fy + 8 + ripple);
  ctx.lineTo(poleTop[0], poleTop[1] + 7);
  ctx.closePath(); ctx.fill(); ctx.stroke();

  if (ship.ghostFire > 0 || ship.onFire > 0) {
    const firePt = shipPt(-halfL * 0.1, 0, hullHeight + 6);
    const flk = 5.5 + Math.sin(game.time * 0.32 + ship.x) * 2.5;
    ctx.fillStyle = ship.ghostFire > 0 ? 'rgba(52, 211, 153, 0.90)' : 'rgba(239, 68, 68, 0.88)';
    ctx.beginPath(); ctx.arc(firePt[0], firePt[1], flk, 0, Math.PI * 2); ctx.fill();
  }
};

window.drawProximityShouts = function(ctx) {
  const shouts = window.proximityShouts || [];
  for (let i = shouts.length - 1; i >= 0; i--) {
    const sh = shouts[i];
    sh.life--;
    if (sh.life <= 0) { shouts.splice(i, 1); continue; }
    const sx = sh.shipRef ? sh.shipRef.x : sh.x;
    const sy = (sh.shipRef ? sh.shipRef.y - (sh.shipRef.width || 24) : sh.y) - 34;

    ctx.save();
    ctx.globalAlpha = Math.min(1, sh.life / 35);
    ctx.font = 'bold 12.5px sans-serif';
    const txt = `📣 ${sh.text}`;
    const tw = Math.min(340, ctx.measureText(txt).width + 22);
    ctx.fillStyle = 'rgba(10, 18, 28, 0.92)'; ctx.strokeStyle = sh.color || '#ffd700'; ctx.lineWidth = 1.8;
    ctx.beginPath(); ctx.roundRect(sx - tw / 2, sy - 24, tw, 24, 6); ctx.fill(); ctx.stroke();
    ctx.fillStyle = '#f8fafc'; ctx.textAlign = 'center';
    drawCanvasIconLabel(ctx, txt, sx, sy - 8, 14, tw - 12);
    ctx.restore();
  }
};

// ============================================================================
// KOMPASS, MINIMAP & PERGAMENT-SEEKARTE [M] (inkl. Meeresströmungen!)
// ============================================================================
window.drawCompassAndMinimap = function(ctx, canvas) {
  const wb = getActiveWorldBounds();
  const cx = 80, cy = canvas.height - 80, r = 48;

  ctx.save();
  ctx.translate(cx, cy);
  ctx.fillStyle = 'rgba(10, 20, 30, 0.92)'; ctx.strokeStyle = '#d4af37'; ctx.lineWidth = 2.5;
  ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill(); ctx.stroke();

  ctx.fillStyle = '#94a3b8'; ctx.font = 'bold 10px sans-serif'; ctx.textAlign = 'center';
  ctx.fillText('N', 0, -r + 13); ctx.fillText('S', 0, r - 5);
  ctx.fillText('E', r - 9, 4);   ctx.fillText('W', -r + 9, 4);

  ctx.save();
  ctx.rotate(wind.angle);
  ctx.fillStyle = '#38bdf8'; ctx.strokeStyle = '#fff'; ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(r - 12, 0); ctx.lineTo(-9, -8); ctx.lineTo(-3, 0); ctx.lineTo(-9, 8); ctx.closePath();
  ctx.fill(); ctx.stroke();
  ctx.restore();

  if (hasNavigatorForWaypoints()) {
    const msTarget = getActiveMissionTargetCoords();
    if (msTarget) {
      const mAng = Math.atan2(msTarget.y - player.y, msTarget.x - player.x);
      ctx.save(); ctx.rotate(mAng);
      ctx.fillStyle = '#ef4444'; ctx.strokeStyle = '#fde047'; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.moveTo(r + 6, 0); ctx.lineTo(r - 6, -6); ctx.lineTo(r - 6, 6); ctx.closePath();
      ctx.fill(); ctx.stroke(); ctx.restore();
    }
    if (game.customWaypoint) {
      const wp = game.customWaypoint;
      const wAng = Math.atan2(wp.y - player.y, wp.x - player.x);
      const distM = Math.round(Math.hypot(wp.x - player.x, wp.y - player.y) / 10);
      ctx.save(); ctx.rotate(wAng);
      ctx.fillStyle = '#a855f7'; ctx.strokeStyle = '#fff'; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.moveTo(r + 7, 0); ctx.lineTo(r - 5, -5.5); ctx.lineTo(r - 5, 5.5); ctx.closePath();
      ctx.fill(); ctx.stroke(); ctx.restore();
      ctx.fillStyle = '#e9d5ff'; ctx.font = 'bold 9.5px sans-serif';
      drawCanvasIconLabel(ctx, `📍 ${distM}sm`, 0, -r - 8, 12);
    }
  }

  ctx.fillStyle = '#ffd700'; ctx.font = 'bold 11px sans-serif';
  ctx.fillText(`Wind ${(wind.speed * 14).toFixed(0)} kn`, 0, r + 16);
  ctx.restore();

  const mw = 200, mh = 200;
  const mx = canvas.width - mw - 14, my = canvas.height - mh - 14;
  const pilotActive = hasShoalPilotRadar();

  ctx.save();
  ctx.fillStyle = 'rgba(6, 20, 34, 0.94)'; ctx.strokeStyle = '#b8860b'; ctx.lineWidth = 2.5;
  ctx.fillRect(mx, my, mw, mh);

  ctx.fillStyle = '#3b5e2b';
  for (const land of wb.lands) {
    if (land.isGhostIsle && game.worldMode !== 'mythology') continue;
    ctx.beginPath();
    land.pts.forEach((p, idx) => {
      const lx = mx + (p[0] / wb.w) * mw, ly = my + (p[1] / wb.h) * mh;
      if (idx === 0) ctx.moveTo(lx, ly); else ctx.lineTo(lx, ly);
    });
    ctx.closePath(); ctx.fill();
  }

  if (pilotActive) {
    ctx.fillStyle = '#fbbf24';
    for (const rf of wb.reefs) ctx.fillRect(mx + (rf.x / wb.w) * mw - 1.5, my + (rf.y / wb.h) * mh - 1.5, 3, 3);
  }

  if (!(game.isMultiplayer && game.mpMode === 'deathmatch')) {
    for (const p of PORTS) {
      ctx.fillStyle = FACTIONS[p.faction] ? FACTIONS[p.faction].color : '#fff';
      ctx.beginPath(); ctx.arc(mx + (p.x / wb.w) * mw, my + (p.y / wb.h) * mh, 2.8, 0, Math.PI * 2); ctx.fill();
    }
    if (game.hideout && game.hideout.foundedPlotId && typeof BASE_PLOTS !== 'undefined') {
      const bp = BASE_PLOTS.find(b => b.id === game.hideout.foundedPlotId);
      if (bp) {
        ctx.fillStyle = '#c084fc';
        ctx.beginPath(); ctx.arc(mx + (bp.x / wb.w) * mw, my + (bp.y / wb.h) * mh, 4.0, 0, Math.PI * 2); ctx.fill();
      }
    }
    const cellW = mw / FOW_COLS, cellH = mh / FOW_ROWS;
    ctx.fillStyle = '#040a12';
    for (let rIdx = 0; rIdx < FOW_ROWS; rIdx += 2) {
      for (let cIdx = 0; cIdx < FOW_COLS; cIdx += 2) {
        if (fowGrid[rIdx * FOW_COLS + cIdx] === 0) ctx.fillRect(mx + cIdx * cellW, my + rIdx * cellH, cellW * 2.15, cellH * 2.15);
      }
    }
  } else {
    // Im Deathmatch Safe-Zone in der Kartenmitte markieren
    ctx.fillStyle = '#2ecc71';
    ctx.beginPath(); ctx.arc(mx + (PORTS[0].x / wb.w) * mw, my + (PORTS[0].y / wb.h) * mh, 4.5, 0, Math.PI * 2); ctx.fill();
  }

  if (game.wololoEnabled && !game.isMultiplayer && typeof WOLOLO_SHRINE !== 'undefined') {
    ctx.fillStyle = '#fde047'; ctx.strokeStyle = '#38bdf8'; ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.arc(mx + (WOLOLO_SHRINE.x / wb.w) * mw, my + (WOLOLO_SHRINE.y / wb.h) * mh, 4.2, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
  }
  const plX = mx + (player.x / wb.w) * mw, plY = my + (player.y / wb.h) * mh;
  ctx.fillStyle = '#fff'; ctx.strokeStyle = '#ffd700'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.arc(plX, plY, 4.5, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
  ctx.strokeStyle = '#b8860b'; ctx.lineWidth = 2.5;
  ctx.strokeRect(mx, my, mw, mh);
  ctx.restore();
};

window.initBigMapWaypointClicks = function() {
  const mc = document.getElementById('bigMapCanvas');
  if (!mc || mc._wpBound) return;
  mc._wpBound = true;

  mc.addEventListener('contextmenu', e => {
    e.preventDefault();
    if (window.game && game.customWaypoint) { game.customWaypoint = null; renderBigMap(); }
  });

  mc.addEventListener('mousedown', e => {
    if (!window.game || !hasNavigatorForWaypoints()) return;
    if (e.button === 2) { game.customWaypoint = null; renderBigMap(); return; }
    const wb = getActiveWorldBounds();
    const rect = mc.getBoundingClientRect();
    game.customWaypoint = {
      x: Math.round(((e.clientX - rect.left) / rect.width) * wb.w),
      y: Math.round(((e.clientY - rect.top) / rect.height) * wb.h)
    };
    SoundFX.play('card');
    renderBigMap();
  });
};

window.renderBigMap = function() {
  initBigMapWaypointClicks();
  const wb = getActiveWorldBounds();
  const mc = document.getElementById('bigMapCanvas');
  if (!mc) return;
  const mctx = mc.getContext('2d');
  const mw = mc.width, mh = mc.height;

  const bgGrad = mctx.createRadialGradient(mw / 2, mh / 2, 60, mw / 2, mh / 2, mw * 0.72);
  bgGrad.addColorStop(0, '#0f3349'); bgGrad.addColorStop(1, '#061926');
  mctx.fillStyle = bgGrad; mctx.fillRect(0, 0, mw, mh);

  mctx.strokeStyle = 'rgba(212, 175, 55, 0.14)'; mctx.lineWidth = 1;
  for (let gx = 80; gx < mw; gx += 100) { mctx.beginPath(); mctx.moveTo(gx, 0); mctx.lineTo(gx, mh); mctx.stroke(); }
  for (let gy = 60; gy < mh; gy += 90) { mctx.beginPath(); mctx.moveTo(0, gy); mctx.lineTo(mw, gy); mctx.stroke(); }

  // Meeresströmungen auf der großen Seekarte einzeichnen, wenn Navigator oder Lotse an Bord ist!
  if (!(game.isMultiplayer && game.mpMode === 'deathmatch') && (canDrawMap() || hasShoalPilotRadar()) && typeof OCEAN_CURRENTS !== 'undefined') {
    mctx.strokeStyle = 'rgba(56, 189, 248, 0.52)';
    mctx.lineWidth = 3.2;
    mctx.setLineDash([8, 6]);
    for (const cur of OCEAN_CURRENTS) {
      const x1 = (cur.x1 / wb.w) * mw, y1 = (cur.y1 / wb.h) * mh;
      const x2 = (cur.x2 / wb.w) * mw, y2 = (cur.y2 / wb.h) * mh;
      mctx.beginPath(); mctx.moveTo(x1, y1); mctx.lineTo(x2, y2); mctx.stroke();
    }
    mctx.setLineDash([]);
  }

  for (const land of wb.lands) {
    if (land.isGhostIsle && game.worldMode !== 'mythology') continue;
    mctx.fillStyle = land.isGhostIsle ? '#064e3b' : '#3d6b35';
    mctx.strokeStyle = land.isGhostIsle ? '#34d399' : '#e7c98a';
    mctx.lineWidth = 2;
    mctx.beginPath();
    land.pts.forEach((p, idx) => {
      const lx = (p[0] / wb.w) * mw, ly = (p[1] / wb.h) * mh;
      if (idx === 0) mctx.moveTo(lx, ly); else mctx.lineTo(lx, ly);
    });
    mctx.closePath(); mctx.fill(); mctx.stroke();
  }

  if (!(game.isMultiplayer && game.mpMode === 'deathmatch')) {
    // Freie Bauplätze nur zeigen, solange der Spieler noch KEINE eigene Kolonie gegründet hat!
    if (typeof BASE_PLOTS !== 'undefined') {
      const ownedId = game.hideout && game.hideout.foundedPlotId;
      for (const bp of BASE_PLOTS) {
        if (ownedId && bp.id !== ownedId) continue;
        const bx = (bp.x / wb.w) * mw, by = (bp.y / wb.h) * mh;
        if (ownedId === bp.id) {
          mctx.fillStyle = '#e9d5ff'; mctx.font = 'bold 12px sans-serif'; mctx.textAlign = 'center';
          drawCanvasIconLabel(mctx, `🏴‍☠️ ${game.hideout.customBaseName || td(bp, 'name')}`, bx, by - 5, 13);
        } else {
          mctx.fillStyle = 'rgba(253, 224, 71, 0.85)';
          mctx.beginPath(); mctx.arc(bx, by, 2.8, 0, Math.PI * 2); mctx.fill();
        }
      }
    }

    for (const p of PORTS) {
      const px = (p.x / wb.w) * mw, py = (p.y / wb.h) * mh;
      mctx.fillStyle = FACTIONS[p.faction] ? FACTIONS[p.faction].color : '#fff';
      mctx.strokeStyle = '#fff'; mctx.lineWidth = 1.5;
      mctx.beginPath(); mctx.arc(px, py, 4.2, 0, Math.PI * 2); mctx.fill(); mctx.stroke();
      mctx.fillStyle = '#f8fafc'; mctx.font = 'bold 9.5px sans-serif'; mctx.textAlign = 'center';
      mctx.fillText(p.name, px, py - 6);
    }

    for (const site of EXPLORATION_SITES) {
      if (site.mapBought && !site.looted) {
        mctx.fillStyle = '#2ecc71'; mctx.font = 'bold 10.5px sans-serif'; mctx.textAlign = 'center';
        mctx.fillText(`✖ ${td(site, 'name')}`, (site.x / wb.w) * mw, (site.y / wb.h) * mh);
      }
    }

    const cellW = mw / FOW_COLS, cellH = mh / FOW_ROWS;
    mctx.fillStyle = '#040b14';
    for (let rIdx = 0; rIdx < FOW_ROWS; rIdx++) {
      for (let cIdx = 0; cIdx < FOW_COLS; cIdx++) {
        if (fowGrid[rIdx * FOW_COLS + cIdx] === 0) mctx.fillRect(cIdx * cellW, rIdx * cellH, cellW + 0.9, cellH + 0.9);
      }
    }
  }

  if (game.wololoEnabled && !game.isMultiplayer && typeof WOLOLO_SHRINE !== 'undefined') {
    const wx = (WOLOLO_SHRINE.x / wb.w) * mw, wy = (WOLOLO_SHRINE.y / wb.h) * mh;
    mctx.fillStyle = '#fde047'; mctx.strokeStyle = '#38bdf8'; mctx.lineWidth = 2;
    mctx.beginPath(); mctx.arc(wx, wy, 5.5, 0, Math.PI * 2); mctx.fill(); mctx.stroke();
    mctx.fillStyle = '#fef08a'; mctx.font = 'bold 11px sans-serif'; mctx.textAlign = 'center';
    drawCanvasIconLabel(mctx, '⛩️ Wololo-Arsenal', wx, wy - 9, 13);
  }
  const plX = (player.x / wb.w) * mw, plY = (player.y / wb.h) * mh;
  mctx.fillStyle = '#fff'; mctx.strokeStyle = '#ffd700'; mctx.lineWidth = 3;
  mctx.beginPath(); mctx.arc(plX, plY, 5.5, 0, Math.PI * 2); mctx.fill(); mctx.stroke();

  const hintEl = document.getElementById('mapFooterHint');
  if (hasNavigatorForWaypoints()) hintEl.innerHTML = `<strong style="color:#2ecc71;">✓</strong> ${t('waypointClickHint')}`;
  else hintEl.innerHTML = `<strong style="color:#ff7675;">⚠️ Kein Navigator an Bord – Zielmarkierungen inaktiv!</strong>`;
};